b) Phần chi phí liên quan đến việc thuê quản lý đối với hoạt động kinh doanh
trò chơi điện tử có thưởng, kinh doanh casino vượt quá 4% doanh thu hoạt động
kinh doanh trò chơi điện tử có thưởng, kinh doanh casino;
c) Chi trả lãi tiền vay của doanh nghiệp có giao dịch liên kết theo quy định của
pháp luật về quản lý thuế đối với doanh nghiệp có giao dịch liên kết;
d) Phần chi cho các khoản có tính chất phúc lợi trực tiếp cho người lao động
vượt quá 01 tháng lương bình quân thực tế thực hiện trong năm tính thuế, bao
gồm: Chi đám hiếu, hỷ của bản thân và gia đình người lao động; chi nghỉ mát; chi
hỗ trợ điều trị khám bệnh, chữa bệnh; chi hỗ trợ bổ sung kiến thức học tập tại cơ
sở giáo dục, cơ sở hoạt động giáo dục nghề nghiệp; chi hỗ trợ gia đình người lao
động bị ảnh hưởng bởi thiên tai, địch họa, tai nạn, ốm đau; chi khen thưởng con
của người lao động có thành tích tốt trong học tập; chi hỗ trợ chi phí đi lại ngày
lễ, tết cho người lao động; chi bảo hiểm tai nạn (không bao gồm trường hợp chi
bảo hiểm tai nạn bắt buộc theo quy định của pháp luật chuyên ngành), bảo hiểm
sức khỏe, bảo hiểm tự nguyện khác cho người lao động (trừ khoản đóng góp
tham gia bảo hiểm hưu trí bổ sung theo quy định của Luật Bảo hiểm xã hội,
khoản chi mua bảo hiểm nhân thọ cho người lao động, bảo hiểm hưu trí tự
nguyện cho người lao động hướng dẫn tại điểm đ khoản này) và những khoản chi
có tính chất phúc lợi khác, cụ thể như sau:
d1) Việc xác định 01 tháng lương bình quân thực tế thực hiện trong năm tính
thuế của doanh nghiệp được xác định bằng quỹ tiền lương thực hiện trong năm
chia cho 12 tháng. Trường hợp doanh nghiệp hoạt động không đủ 12 tháng thì việc
xác định 01 tháng lương bình quân thực tế thực hiện trong năm tính thuế được xác
định bằng quỹ tiền lương thực hiện trong năm chia cho số tháng thực tế hoạt động
trong năm;
d2) Quỹ tiền lương thực hiện là tổng số tiền lương thực tế đã chi trả của năm
quyết toán đó đến thời hạn cuối cùng nộp hồ sơ quyết toán theo quy định (không
bao gồm số tiền trích lập quỹ dự phòng tiền lương của năm trước chi trong năm
quyết toán thuế);
đ) Phần chi vượt mức 05 triệu đồng/tháng/người để đóng góp tham gia bảo hiểm
hưu trí bổ sung theo Luật Bảo hiểm xã hội hoặc quỹ có tính chất an sinh xã hội, mua
bảo hiểm hưu trí tự nguyện, bảo hiểm nhân thọ cho người lao động. Phần vượt mức
quy định của pháp luật về bảo hiểm xã hội, về bảo hiểm y tế để trích nộp các quỹ có
tính chất an sinh xã hội (bảo hiểm xã hội, bảo hiểm hưu trí bổ sung bắt buộc), Quỹ
bảo hiểm y tế và Quỹ bảo hiểm thất nghiệp cho người lao động, cụ thể như sau:
đ1) Khoản tham gia bảo hiểm hưu trí bổ sung theo Luật Bảo hiểm xã hội hoặc
quỹ có tính chất an sinh xã hội, mua bảo hiểm hưu trí tự nguyện, bảo hiểm nhân
thọ cho người lao động được tính vào chi phí được trừ ngoài việc không vượt mức
quy định tại điểm này còn phải được ghi cụ thể điều kiện hưởng và mức hưởng tại
một trong các hồ sơ sau: Hợp đồng lao động; Thỏa ước lao động tập thể; Quy chế
tài chính của Công ty, Tổng công ty, Tập đoàn; Quy chế thưởng do Chủ tịch Hội
đồng quản trị Tổng giám đốc, Giám đốc quy định theo quy chế tài chính của Công
ty, Tổng công ty, Tập đoàn;
đ2) Doanh nghiệp không được tính vào chi phí đối với các khoản chi tham gia
bảo hiểm hưu trí bổ sung theo Luật Bảo hiểm xã hội hoặc quỹ có tính chất an sinh
xã hội, mua bảo hiểm hưu trí tự nguyện, bảo hiểm nhân thọ cho người lao động
nếu doanh nghiệp không thực hiện đầy đủ các nghĩa vụ về bảo hiểm bắt buộc cho
người lao động (kể cả trường hợp nợ tiền bảo hiểm bắt buộc).
5. Trích lập và sử dụng các khoản dự phòng không theo đúng quy định của
pháp luật về trích lập dự phòng: Dự phòng giảm giá hàng tồn kho, dự phòng tổn
thất các khoản đầu tư tài chính, dự phòng nợ phải thu khó đòi, dự phòng bảo hành
sản phẩm, hàng hoá, công trình xây lắp và dự phòng rủi ro nghề nghiệp của doanh
nghiệp thẩm định giá, doanh nghiệp cung cấp dịch vụ kiểm toán độc lập.
6. Chi khấu hao tài sản cố định thuộc một trong các trường hợp sau:
a) Chi khấu hao đối với tài sản cố định không sử dụng cho hoạt động sản xuất,
kinh doanh hàng hóa, dịch vụ.
Riêng tài sản cố định phục vụ cho người lao động làm việc tại doanh nghiệp,
bao gồm: Nhà nghỉ giữa ca, nhà ăn giữa ca, nhà thay quần áo, nhà vệ sinh, phòng
hoặc trạm y tế để khám, chữa bệnh, cơ sở đào tạo, dạy nghề, thư viện, nhà trẻ, khu
thể thao và các thiết bị, nội thất đủ điều kiện là tài sản cố định lắp đặt trong các công
trình nêu trên; bể chứa nước sạch, nhà để xe; xe đưa đón người lao động, nhà ở trực
tiếp cho người lao động; chi phí xây dựng cơ sở vật chất, chi phí mua sắm máy móc,
thiết bị là tài sản cố định dùng để tổ chức hoạt động giáo dục nghề nghiệp và những
tài sản dùng để phục vụ trực tiếp cho người lao động trong doanh nghiệp được trích
khấu hao tính vào chi phí được trừ khi xác định thu nhập chịu thuế;
b) Chi khấu hao đối với tài sản cố định không có giấy tờ chứng minh thuộc
quyền sở hữu của doanh nghiệp (trừ tài sản cố định thuê tài chính);
c) Chi khấu hao đối với tài sản cố định không được quản lý, theo dõi, hạch
toán trong sổ sách kế toán của doanh nghiệp theo chế độ quản lý tài sản cố định và
hạch toán kế toán hiện hành;
d) Phần trích khấu hao không đúng hoặc vượt mức quy định hiện hành của Bộ
trưởng Bộ Tài chính về chế độ quản lý, sử dụng và trích khấu hao tài sản cố định,
cụ thể như sau:
d1) Doanh nghiệp trích khấu hao tài sản cố định theo quy định của Bộ trưởng Bộ
Tài chính về chế độ quản lý, sử dụng và trích khấu hao tài sản cố định kể cả trường
hợp khấu hao nhanh nhưng phải đáp ứng điều kiện đảm bảo kinh doanh có lãi;
d2) Đối với tài sản là công cụ, dụng cụ, bao bì luân chuyển không đáp ứng đủ
điều kiện xác định là tài sản cố định theo quy định (bao gồm các công cụ, dụng cụ,
bao bì luân chuyển không đáp ứng đủ điều kiện xác định là tài sản cố định phục vụ
cho người lao động nêu tại điểm a khoản này) thì chi phí mua tài sản nêu trên được
phân bổ dần vào chi phí hoạt động sản xuất kinh doanh trong kỳ nhưng tối đa
không quá 03 năm;
đ) Khấu hao đối với tài sản cố định đã khấu hao hết giá trị trừ trường hợp tài
sản cố định được cơ quan có thẩm quyền cho phép đánh giá lại;
e) Một số trường hợp cụ thể được xác định như sau:
e1) Không được tính vào chi phí được trừ khi xác định thu nhập chịu thuế đối
với: Phần trích khấu hao tương ứng với nguyên giá vượt trên 1,6 tỷ đồng/xe đối
với ô tô chở người từ 9 chỗ ngồi trở xuống (trừ ô tô dùng cho kinh doanh vận tải
hành khách, kinh doanh du lịch, khách sạn; ô tô dùng để làm mẫu và lái thử cho
kinh doanh ô tô); phần trích khấu hao đối với tài sản cố định là máy bay, trực
thăng, tàu lượn, du thuyền không sử dụng kinh doanh vận chuyển hàng hóa, hành
khách, kinh doanh du lịch, khách sạn. Trường hợp doanh nghiệp có chuyển
nhượng, thanh lý xe ô tô chở người từ 9 chỗ ngồi trở xuống thì giá trị còn lại của
xe được xác định bằng nguyên giá thực mua tài sản cố định trừ đi số khấu hao lũy
kế của tài sản cố định theo chế độ quản lý sử dụng và trích khấu hao tài sản cố định
tính đến thời điểm chuyển nhượng, thanh lý xe.
Ô tô chở người từ 9 chỗ ngồi trở xuống chuyên kinh doanh vận tải hành khách,
du lịch và khách sạn là các ô tô được đăng ký tên doanh nghiệp mà doanh nghiệp
này trong Giấy chứng nhận đăng ký doanh nghiệp hoặc Giấy chứng nhận đăng ký
kinh doanh có đăng ký một trong các ngành nghề: Vận tải hành khách, kinh doanh
du lịch, khách sạn và được cấp phép kinh doanh theo quy định tại các văn bản
pháp luật về kinh doanh vận tải, hành khách, du lịch, khách sạn. Máy bay, trực
thăng, tàu lượn, du thuyền không sử dụng cho mục đích kinh doanh vận chuyển
hàng hoá, hành khách, khách du lịch là máy bay, trực thăng, tàu lượn, du thuyền
của các doanh nghiệp đăng ký và hạch toán trích khấu hao tài sản cố định nhưng
trong Giấy chứng nhận đăng ký doanh nghiệp hoặc Giấy chứng nhận đăng ký kinh
doanh của doanh nghiệp không đăng ký ngành nghề vận tải hàng hoá, vận tải hành
khách, kinh doanh du lịch, khách sạn;
e2) Đối với công trình trên đất vừa sử dụng cho sản xuất, kinh doanh vừa sử
dụng cho mục đích khác thì không được tính khấu hao vào chi phí được trừ đối với
giá trị công trình trên đất tương ứng phần diện tích không sử dụng vào hoạt động
sản xuất kinh doanh hoặc không sử dụng phục vụ cho người lao động làm việc tại
doanh nghiệp theo quy định tại điểm a khoản này.
Doanh nghiệp được trích khấu hao tính vào chi phí được trừ khi xác định thu
nhập chịu thuế theo đúng mức trích khấu hao và thời gian sử dụng tài sản cố định
theo quy định của Bộ trưởng Bộ Tài chính đối với các công trình trên đất như trụ
sở văn phòng, nhà xưởng, cửa hàng phục vụ cho hoạt động sản xuất, kinh doanh
của doanh nghiệp nếu đáp ứng các điều kiện như sau: Có Giấy chứng nhận quyền
sử dụng đất mang tên doanh nghiệp (trong trường hợp đất thuộc quyền sử dụng của
doanh nghiệp) hoặc có hợp đồng thuê đất, mượn đất giữa doanh nghiệp với đơn vị,
cá nhân có đất và đại diện doanh nghiệp phải chịu trách nhiệm trước pháp luật về
tính chính xác của hợp đồng (trong trường hợp đất đi thuê hoặc đi mượn); có hóa
đơn thanh toán khối lượng công trình xây dựng bàn giao kèm theo hợp đồng xây
dựng công trình, thanh lý hợp đồng (nếu có), quyết toán giá trị công trình xây dựng
mang tên, địa chỉ và mã số thuế của doanh nghiệp; công trình trên đất được quản
lý, theo dõi hạch toán theo quy định hiện hành về quản lý tài sản cố định;
e3) Trường hợp tài sản cố định thuộc quyền sở hữu của doanh nghiệp đang
dùng cho sản xuất, kinh doanh nhưng phải tạm thời dừng do sản xuất theo mùa vụ
với thời gian dưới 09 tháng; tạm thời dừng để sửa chữa, để di dời di chuyển địa
điểm, để bảo trì, bảo dưỡng theo định kỳ, với thời gian dưới 12 tháng, sau đó tài
sản cố định tiếp tục đưa vào phục vụ cho hoạt động sản xuất kinh doanh thì trong
khoảng thời gian tạm dừng đó doanh nghiệp được trích khấu hao và khoản chi phí
khấu hao tài sản cố định trong thời gian tạm dừng được tính vào chi phí được trừ
khi xác định thu nhập chịu thuế.
Doanh nghiệp phải lưu giữ và cung cấp đầy đủ hồ sơ, nguyên nhân của việc
tạm dừng tài sản cố định khi cơ quan thuế yêu cầu;
e4) Quyền sử dụng đất lâu dài không được trích khấu hao và phân bổ vào chi
phí được trừ khi xác định thu nhập chịu thuế. Quyền sử dụng đất có thời hạn nếu có
đầy đủ hóa đơn, chứng từ và thực hiện đúng quy định của pháp luật, có tham gia vào
hoạt động sản xuất, kinh doanh thì được phân bổ dần vào chi phí được trừ theo thời
hạn được phép sử dụng đất ghi trong Giấy chứng nhận quyền sử dụng đất hoặc thời
gian cho thuê đất ghi trong hợp đồng giao đất/cho thuê đất (bao gồm cả trường hợp
đầu tư xây dựng mới, dừng hoạt động để sửa chữa, để đầu tư xây dựng mới).
Trường hợp doanh nghiệp mua tài sản cố định hữu hình là nhà cửa, vật kiến trúc
gắn liền với quyền sử dụng đất lâu dài thì giá trị quyền sử dụng đất phải xác định
riêng và ghi nhận là tài sản cố định vô hình; tài sản cố định hữu hình là nhà cửa, vật
kiến trúc thì nguyên giá là giá mua thực tế phải trả cộng với các khoản chi phí liên
quan trực tiếp đến việc đưa tài sản cố định hữu hình vào sử dụng. Giá trị quyền sử
dụng đất được xác định theo giá ghi trên hợp đồng mua bất động sản (tài sản) phù
hợp với giá thị trường nhưng không được thấp hơn giá đất tại bảng giá đất do Ủy
ban nhân dân tỉnh, thành phố trực thuộc Trung ương quy định tại thời điểm mua tài
sản. Trường hợp doanh nghiệp mua tài sản cố định hữu hình là nhà cửa, vật kiến
trúc gắn liền với quyền sử dụng đất lâu dài không tách riêng được giá trị quyền sử
dụng đất thì giá trị quyền sử dụng đất được xác định theo giá đất tại bảng giá đất do
Ủy ban nhân dân tỉnh, thành phố trực thuộc Trung ương quy định tại thời điểm mua
tài sản.
Trường hợp doanh nghiệp có chuyển nhượng một phần vốn hoặc chuyển
nhượng toàn bộ doanh nghiệp khác theo quy định của pháp luật, nếu có chuyển
giao tài sản thì doanh nghiệp nhận chuyển nhượng chỉ được trích khấu hao tài sản
cố định vào chi phí được trừ đối với các tài sản chuyển giao đủ điều kiện trích
khấu hao theo giá trị còn lại trên sổ sách kế toán tại doanh nghiệp chuyển nhượng.
7. Các khoản chi phí trích trước theo kỳ hạn, theo chu kỳ mà đến hết kỳ hạn,
hết chu kỳ chưa chi hoặc chi không hết, cụ thể như sau:
a) Các khoản trích trước bao gồm: Khoản trích trước về sửa chữa lớn tài sản cố
định theo quy định của pháp luật kế toán; các khoản trích trước đối với hoạt động
đã tính doanh thu nhưng còn tiếp tục phải thực hiện nghĩa vụ theo hợp đồng (kể cả
trường hợp doanh nghiệp có hoạt động cho thuê tài sản, hoạt động kinh doanh dịch
vụ trong nhiều năm nhưng có thu tiền trước của khách hàng và đã tính toàn bộ vào
doanh thu của năm thu tiền) và các khoản trích trước khác;
b) Trường hợp doanh nghiệp có hoạt động sản xuất, kinh doanh đã ghi nhận
doanh thu tính thuế thu nhập doanh nghiệp nhưng chưa phát sinh đầy đủ chi phí thì
được trích trước các khoản chi phí theo quy định vào chi phí được trừ tương ứng
với doanh thu đã ghi nhận khi xác định thu nhập chịu thuế thu nhập doanh nghiệp.
Khi kết thúc hợp đồng, doanh nghiệp phải tính toán xác định chính xác số chi phí
thực tế căn cứ các hoá đơn, chứng từ hợp pháp thực tế đã phát sinh để điều chỉnh
tăng chi phí (trường hợp chi phí thực tế phát sinh lớn hơn số đã trích trước) hoặc
giảm chi phí (trường hợp chi phí thực tế phát sinh nhỏ hơn số đã trích trước) vào
kỳ tính thuế kết thúc hợp đồng.
8. Chi cho người lao động thuộc một trong các trường hợp sau:
a) Chi tiền lương, tiền công và các khoản phải trả khác cho người lao động
doanh nghiệp đã hạch toán vào chi phí sản xuất kinh doanh trong kỳ nhưng thực tế
không chi trả hoặc không có chứng từ thanh toán theo quy định của pháp luật;
b) Các khoản tiền lương, tiền công, tiền thưởng cho người lao động không
được ghi cụ thể điều kiện được hưởng và mức được hưởng tại một trong các hồ sơ
sau: Hợp đồng lao động hoặc văn bản của doanh nghiệp nước ngoài cử người sang
làm việc tại Việt Nam (đối với trường hợp người nước ngoài được điều chuyển
hoặc di chuyển trong nội bộ Tập đoàn, giữa công ty mẹ với công ty con); Thoả ước
lao động tập thể; Quy chế tài chính của Công ty, Tổng công ty, Tập đoàn; Quy chế
thưởng do Chủ tịch Hội đồng quản trị, Tổng giám đốc, Giám đốc quy định theo
quy chế tài chính của Công ty, Tổng công ty, Tập đoàn.
b1) Trường hợp doanh nghiệp ký hợp đồng lao động với người nước ngoài trong
đó có ghi khoản chi về tiền học cho con của người nước ngoài học tại Việt Nam theo
bậc học từ mầm non đến trung học phổ thông được doanh nghiệp trả có tính chất tiền
lương, tiền công và có đầy đủ hoá đơn, chứng từ theo quy định thì được tính vào chi
phí được trừ khi xác định thu nhập chịu thuế thu nhập doanh nghiệp;
b2) Trường hợp doanh nghiệp ký hợp đồng lao động với người lao động trong
đó có ghi khoản chi về tiền nhà do doanh nghiệp trả cho người lao động, khoản chi
trả này có tính chất tiền lương, tiền công và có đầy đủ hoá đơn, chứng từ theo quy
định thì được tính vào chi phí được trừ khi xác định thu nhập chịu thuế thu nhập
doanh nghiệp;
b3) Trường hợp doanh nghiệp Việt Nam ký hợp đồng với doanh nghiệp nước
ngoài trong đó nêu rõ doanh nghiệp Việt Nam phải chịu các chi phí về chỗ ở cho
các chuyên gia nước ngoài trong thời gian công tác ở Việt Nam thì tiền thuê nhà
cho các chuyên gia nước ngoài làm việc tại Việt Nam do doanh nghiệp Việt Nam
chi trả được tính vào chi phí được trừ khi xác định thu nhập chịu thuế thu nhập
doanh nghiệp;
c) Chi tiền lương, tiền công và các khoản phụ cấp phải trả cho người lao động
nhưng hết thời hạn nộp hồ sơ quyết toán thuế năm thực tế chưa chi; trừ trường hợp
doanh nghiệp có trích lập quỹ lương dự phòng. Mức dự phòng hàng năm do doanh
nghiệp quyết định nhưng không quá 17% quỹ tiền lương thực hiện.
Việc trích lập quỹ lương dự phòng phải đảm bảo sau khi trích lập, doanh
nghiệp không bị lỗ, nếu doanh nghiệp bị lỗ thì không được trích đủ 17%. Trường
hợp năm trước doanh nghiệp có trích lập quỹ lương dự phòng mà sau 6 tháng kể từ
ngày kết thúc kỳ tính thuế doanh nghiệp chưa sử dụng hoặc sử dụng không hết quỹ
lương dự phòng thì doanh nghiệp phải tính giảm chi phí của năm sau;
d) Tiền lương, tiền công của chủ doanh nghiệp tư nhân, chủ công ty trách
nhiệm hữu hạn một thành viên do một cá nhân làm chủ; thù lao trả cho các sáng
lập viên, thành viên của hội đồng thành viên, hội đồng quản trị mà những người
này không trực tiếp tham gia điều hành sản xuất, kinh doanh;
đ) Phần chi trang phục bằng hiện vật cho người lao động không có hóa đơn,
chứng từ. Phần chi trang phục bằng tiền cho người lao động vượt quá 05 triệu
đồng/người/năm.
Trường hợp doanh nghiệp có chi trang phục cả bằng tiền và hiện vật cho người
lao động để được tính vào chi phí được trừ thì mức chi tối đa đối với chi bằng tiền
không vượt quá 05 triệu đồng/người/năm, bằng hiện vật phải có hóa đơn, chứng từ;
e) Chi thưởng sáng kiến, cải tiến mà doanh nghiệp không có quy chế quy định
cụ thể về việc chi thưởng sáng kiến, cải tiến và không có hội đồng nghiệm thu sáng
kiến, cải tiến;
g) Chi phụ cấp phương tiện đi lại đi nghỉ phép không đúng theo quy định của
Bộ luật Lao động;
h) Chi phụ cấp cho người lao động đi công tác, chi phí đi lại và tiền thuê chỗ ở
cho người lao động đi công tác nếu có đầy đủ hóa đơn, chứng từ được tính vào chi
phí được trừ khi xác định thu nhập chịu thuế. Trường hợp doanh nghiệp cử người
lao động đi công tác (bao gồm công tác trong nước và công tác nước ngoài) nếu có
phát sinh chi phí từ 05 triệu đồng trở lên mà các khoản chi phí này được thanh toán
bởi cá nhân bằng dịch vụ thanh toán không dùng tiền mặt thì xác định đủ điều kiện
là hình thức thanh toán không dùng tiền mặt của doanh nghiệp và tính vào chi phí
được trừ nếu đáp ứng đủ các điều kiện sau: Có hóa đơn, chứng từ theo quy định
của pháp luật về kế toán, pháp luật về hóa đơn, chứng từ do người cung cấp hàng
hóa, dịch vụ giao xuất; doanh nghiệp có quyết định hoặc văn bản cử người lao
động đi công tác; quy chế tài chính hoặc quy chế nội bộ của doanh nghiệp cho
phép người lao động được phép thanh toán khoản công tác phí, mua vé phương
tiện đi lại bởi cá nhân bằng dịch vụ thanh toán không dùng tiền mặt và khoản chi
này sau đó được doanh nghiệp thanh toán lại cho người lao động.
Trường hợp doanh nghiệp có khoán tiền đi lại, tiền ở, phụ cấp cho người lao
động đi công tác và thực hiện đúng theo quy chế tài chính hoặc quy chế nội bộ của
doanh nghiệp thì được tính vào chi phí được trừ khoản chi khoán tiền đi lại, tiền ở,
tiền phụ cấp;
i) Các khoản chi được trừ sau đây nhưng nếu chi không đúng đối tượng, không
đúng mục đích:
i1) Các khoản chi thêm cho lao động nữ, bao gồm: Chi cho công tác đào tạo lại
nghề cho lao động nữ trong trường hợp nghề cũ không còn phù hợp phải chuyển
đổi sang nghề khác theo quy hoạch phát triển của doanh nghiệp, bao gồm học phí
(nếu có) cộng với chênh lệch tiền lương ngạch bậc (đảm bảo 100% lương cho
người đi học); chi phí tiền lương và phụ cấp (nếu có) cho giáo viên dạy ở nhà trẻ,
mẫu giáo do doanh nghiệp tổ chức và quản lý; chi phí tổ chức khám sức khoẻ thêm
trong năm như khám bệnh nghề nghiệp, mãn tính hoặc phụ khoa cho nữ công nhân
viên; chi bồi dưỡng cho lao động nữ sau khi sinh con; phụ cấp làm thêm giờ cho
lao động nữ trong trường hợp vì lý do khách quan người lao động nữ không nghỉ
sau khi sinh con, nghỉ cho con bú mà ở lại làm việc cho doanh nghiệp được trả
theo chế độ hiện hành, kể cả trường hợp trả lương theo sản phẩm mà lao động nữ
vẫn làm việc trong thời gian không nghỉ theo chế độ;
i2) Các khoản chi thêm cho lao động là người dân tộc thiểu số được tính vào
chi phí được trừ bao gồm: Học phí đi học (nếu có) cộng với chênh lệch tiền lương
ngạch bậc (đảm bảo 100% lương cho người đi học); tiền hỗ trợ về nhà ở, bảo hiểm
xã hội, bảo hiểm y tế cho người dân tộc thiểu số trong trường hợp chưa được Nhà
nước hỗ trợ theo chế độ quy định;
k) Chi trả trợ cấp mất việc làm, trợ cấp thôi việc, chi bồi thường, trợ cấp cho
người bị tai nạn lao động, bệnh nghề nghiệp cho người lao động không theo đúng
quy định;
l) Chi phí mua thẻ hội viên sân gôn, chi phí chơi gôn.
9. Chi trả lãi tiền vay tương ứng với phần vốn điều lệ (đối với doanh nghiệp tư
nhân là vốn đầu tư) đã đăng ký còn thiếu theo tiến độ góp vốn ghi trong điều lệ của
doanh nghiệp nhưng tiến độ góp vốn tối đa không được vượt quá thời hạn góp vốn
theo quy định của Luật Doanh nghiệp kể cả trường hợp doanh nghiệp đã đi vào sản
xuất kinh doanh; chi trả lãi tiền vay trong quá trình đầu tư đã được ghi nhận vào
giá trị của tài sản, giá trị công trình đầu tư.
a) Trường hợp doanh nghiệp đã góp đủ vốn điều lệ, trong quá trình kinh doanh
có khoản chi trả lãi tiền vay để đầu tư vào doanh nghiệp khác thì khoản chi này
được tính vào chi phí được trừ khi xác định thu nhập chịu thuế;
b) Chi trả lãi tiền vay tương ứng với vốn điều lệ còn thiếu theo tiến độ góp vốn
ghi trong điều lệ của doanh nghiệp nhưng tiến độ góp vốn tối đa không được vượt
quá thời hạn góp vốn theo quy định của Luật Doanh nghiệp không được trừ khi
xác định thu nhập chịu thuế được xác định như sau:
b1) Trường hợp số tiền vay nhỏ hơn hoặc bằng số vốn điều lệ còn thiếu thì
toàn bộ lãi tiền vay là khoản chi không được trừ;
b2) Trường hợp số tiền vay lớn hơn số vốn điều lệ còn thiếu theo tiến độ góp
vốn thì xác định như sau: Nếu doanh nghiệp phát sinh nhiều khoản vay thì khoản
chi trả lãi tiền vay không được trừ bằng tỷ lệ (%) giữa vốn điều lệ còn thiếu trên
tổng số tiền vay nhân với tổng số lãi vay; nếu doanh nghiệp chỉ phát sinh một
khoản vay thì khoản chi trả lãi tiền vay không được trừ bằng số vốn điều lệ còn
thiếu nhân với lãi suất của khoản vay nhân với thời gian góp vốn điều lệ còn thiếu.
10. Phần chi phí trả lãi tiền vay vốn sản xuất kinh doanh của đối tượng không
phải là tổ chức tín dụng vượt quá mức quy định tại Bộ luật Dân sự.
11. Phần chi phí được phép thu hồi vượt quá tỷ lệ quy định tại hợp đồng dầu
khí được duyệt; trường hợp hợp đồng dầu khí không quy định về tỷ lệ thu hồi chi
phí thì phần chi phí vượt trên 35% không được tính vào chi phí được trừ; các chi
phí không được tính vào chi phí thu hồi gồm:
a) Các khoản chi quy định tại Điều 10 của Nghị định này;
b) Chi phí phát sinh trước khi hợp đồng dầu khí có hiệu lực, trừ trường hợp đã
được thỏa thuận trong hợp đồng dầu khí hoặc theo quyết định của Thủ tướng
Chính phủ;
c) Các loại hoa hồng dầu khí và các khoản chi khác không tính vào chi phí thu
hồi theo hợp đồng;
d) Chi lãi đối với khoản đầu tư cho tìm kiếm, thăm dò, phát triển mỏ và khai
thác dầu khí;
đ) Tiền phạt, tiền bồi thường thiệt hại;
e) Các khoản chi khác không được tính vào chi phí thu hồi theo Luật Dầu khí,
thỏa thuận tại hợp đồng dầu khí, chi phí vượt tỷ lệ để lại quy định tại Điều ước
quốc tế.
Bộ trưởng Bộ Tài chính quy định chi tiết khoản này.
12. Thuế giá trị gia tăng đầu vào đã được khấu trừ hoặc hoàn thuế; thuế giá trị
gia tăng nộp theo phương pháp khấu trừ; thuế giá trị gia tăng đầu vào của tài sản
cố định là ô tô từ 9 chỗ ngồi trở xuống vượt mức quy định được khấu trừ theo quy
định tại các văn bản pháp luật về thuế giá trị gia tăng; thuế thu nhập doanh nghiệp,
trừ trường hợp doanh nghiệp nộp thay thuế thu nhập doanh nghiệp của doanh
nghiệp nước ngoài mà theo thoả thuận tại hợp đồng với doanh nghiệp nước ngoài,
doanh thu của doanh nghiệp nước ngoài nhận được không bao gồm thuế thu nhập
doanh nghiệp; thuế thu nhập cá nhân, trừ trường hợp doanh nghiệp ký hợp đồng
lao động quy định tiền lương, tiền công trả cho người lao động không bao gồm
thuế thu nhập cá nhân; tiền chậm nộp theo quy định pháp luật về quản lý thuế.
Phần thuế giá trị gia tăng nộp theo phương pháp khấu trừ quy định tại điểm
này không bao gồm phần thuế giá trị gia tăng đầu ra của hàng biếu, hàng tặng
không thu tiền theo quy định của pháp luật về thuế giá trị gia tăng phục vụ hoạt
động sản xuất, kinh doanh của doanh nghiệp; phần thuế giá trị gia tăng phải nộp
phát sinh của hàng hóa, dịch vụ sử dụng để tài trợ theo quy định tại điểm đ khoản 2
Điều 9 của Nghị định này; phần thuế giá trị gia tăng của hàng hóa, dịch vụ đầu vào
có liên quan trực tiếp đến sản xuất, kinh doanh của doanh nghiệp chưa được khấu
trừ hết nhưng không thuộc trường hợp hoàn thuế. Số thuế giá trị gia tăng đầu vào
khi đã được tính vào chi phí được trừ thì không được khấu trừ với số thuế giá trị
gia tăng đầu ra.
13. Chi đóng góp hình thành nguồn chi phí quản lý cho cấp trên; phần chi đóng
góp vào các Hội được thành lập theo quy định của Nghị định số 126/2024/NĐ-CP
ngày 08 tháng 10 năm 2024 của Chính phủ vượt quá mức quy định của Hội.
14. Chi trả tiền điện, tiền nước đối với những hợp đồng điện, nước do chủ sở
hữu là tổ chức, hộ gia đình, cá nhân cho thuê địa điểm sản xuất, kinh doanh ký trực
tiếp với đơn vị cung cấp điện, nước không có đủ chứng từ thuộc một trong các
trường hợp sau:
a) Trường hợp doanh nghiệp thuê địa điểm sản xuất, kinh doanh trực tiếp
thanh toán tiền điện, nước cho nhà cung cấp điện, nước không có các hoá đơn
thanh toán tiền điện, nước và hợp đồng thuê địa điểm sản xuất, kinh doanh;
b) Trường hợp doanh nghiệp thuê địa điểm sản xuất, kinh doanh thanh toán
tiền điện, nước với chủ sở hữu cho thuê địa điểm sản xuất, kinh doanh không có
chứng từ thanh toán tiền điện, nước đối với người cho thuê địa điểm sản xuất, kinh
doanh phù hợp với số lượng điện, nước thực tế tiêu thụ và hợp đồng thuê địa điểm
sản xuất kinh doanh.
15. Phần chi phí thuê tài sản cố định vượt quá mức phân bổ theo số năm mà
bên đi thuê trả tiền trước.
a) Đối với chi phí sửa chữa, nâng cấp tài sản cố định đi thuê mà trong hợp
đồng thuê tài sản quy định bên đi thuê có trách nhiệm sửa chữa, nâng cấp tài sản
trong thời gian thuê thì chi phí sửa chữa, nâng cấp tài sản cố định đi thuê được
phép hạch toán vào chi phí hoặc phân bổ dần vào chi phí nhưng thời gian tối đa
không quá 03 năm;
b) Trường hợp doanh nghiệp có chi các khoản chi phí để có các tài sản không
thuộc tài sản cố định như: Chi về mua và sử dụng các tài liệu kỹ thuật, bằng sáng
chế, giấy phép chuyển giao công nghệ, nhãn hiệu thương mại, lợi thế kinh doanh,
quyền sử dụng thương hiệu thì các khoản chi này được phân bổ dần vào chi phí
kinh doanh nhưng tối đa không quá 03 năm;
c) Trường hợp doanh nghiệp có góp vốn bằng giá trị lợi thế kinh doanh, giá trị
quyền sử dụng thương hiệu thì giá trị lợi thế kinh doanh, giá trị quyền sử dụng thương
hiệu góp vốn không tính vào chi phí được trừ khi xác định thu nhập chịu thuế.
16. Lỗ chênh lệch tỷ giá hối đoái do đánh giá lại các khoản mục tiền tệ có gốc
ngoại tệ cuối kỳ tính thuế, bao gồm chênh lệch tỷ giá hối đoái do đánh giá lại số dư
cuối năm là tiền mặt, tiền gửi, tiền đang chuyển, các khoản nợ phải thu có gốc
ngoại tệ (trừ lỗ chênh lệch tỷ giá hối đoái do đánh giá lại các khoản nợ phải trả có
gốc ngoại tệ cuối kỳ tính thuế).
a) Trong giai đoạn sản xuất, kinh doanh, kể cả việc đầu tư xây dựng để hình
thành tài sản cố định của doanh nghiệp đang hoạt động, chênh lệch tỷ giá hối đoái
phát sinh từ các giao dịch bằng ngoại tệ của các khoản mục tiền tệ có gốc ngoại tệ
sẽ được hạch toán vào doanh thu hoạt động tài chính hoặc chi phí tài chính trong
kỳ tính thuế;
b) Đối với khoản nợ phải thu, khoản cho vay, tiền mặt, tiền gửi, tiền đang
chuyển có gốc ngoại tệ phát sinh trong kỳ, chênh lệch tỷ giá hối đoái được tính vào
chi phí được trừ là khoản chênh lệch giữa tỷ giá tại thời điểm phát sinh với tỷ giá
tại thời điểm ghi nhận ban đầu.
17. Chi tài trợ, chi ủng hộ địa phương, chi ủng hộ các đoàn thể, tổ chức xã hội,
chi từ thiện, trừ chi ủng hộ, tài trợ quy định tại điểm đ khoản 2 Điều 9 của Nghị
định này.
18. Chi về đầu tư xây dựng cơ bản trong giai đoạn đầu tư để hình thành tài sản
cố định.
a) Khi bắt đầu hoạt động sản xuất, kinh doanh, doanh nghiệp chưa phát sinh
doanh thu nhưng có phát sinh các khoản chi thường xuyên để duy trì hoạt động sản
xuất, kinh doanh của doanh nghiệp (không phải là các khoản chi đầu tư xây dựng
để hình thành tài sản cố định) mà các khoản chi này đáp ứng các điều kiện theo
quy định thì khoản chi này được tính vào chi phí được trừ khi xác định thu nhập
chịu thuế;
b) Trường hợp trong giai đoạn đầu tư, doanh nghiệp có phát sinh khoản chi trả
tiền vay thì khoản chi này được tính vào giá trị đầu tư. Trường hợp trong giai đoạn
đầu tư xây dựng cơ bản, doanh nghiệp phát sinh cả khoản chi trả lãi tiền vay và thu
từ lãi tiền gửi thì được bù trừ giữa khoản chi trả lãi tiền vay và thu từ lãi tiền gửi,
sau khi bù trừ phần chênh lệch còn lại ghi giảm giá trị đầu tư.
19. Khoản chi liên quan trực tiếp đến việc phát hành cổ phiếu (trừ cổ phiếu
thuộc loại nợ phải trả) và cổ tức của cổ phiếu (trừ cổ tức của cổ phiếu thuộc loại nợ
phải trả), mua cổ phiếu quỹ, cổ phiếu mua lại của chính mình và các khoản chi
khác liên quan trực tiếp đến việc tăng, giảm vốn chủ sở hữu của doanh nghiệp.
20. Số tiền cấp quyền khai thác khoáng sản vượt mức tiền khai thác khoáng
sản phải nộp hàng năm theo quy định của pháp luật về khoáng sản.
a) Khi thực hiện quyết toán số tiền cấp quyền khai thác khoáng sản theo quy
định của pháp luật về khoáng sản, trường hợp số tiền đã nộp nhỏ hơn số phải nộp
sau khi quyết toán thì số tiền cấp quyền khai thác khoáng sản nộp bổ sung được
tính vào chi phí được trừ tại kỳ tính thuế phát sinh khoản nộp bổ sung của doanh
nghiệp khai thác, thu hồi khoáng sản.
b) Trường hợp các giấy phép khai thác khoáng sản, văn bản cho phép khai
thác, thu hồi khoáng sản còn thời hạn khai thác, thu hồi khoáng sản tính đến thời
điểm Nghị định này có hiệu lực thì tiền cấp quyền khai thác khoáng sản tính vào
chi phí được trừ được xác định theo số tiền cấp quyền khai thác khoáng sản còn
phải nộp sau quyết toán theo quy định của pháp luật về khoáng sản phân bổ đều
cho số năm còn được khai thác, thu hồi.
c) Đối với tiền cấp quyền khai thác khoáng sản đã tính vào chi phí được trừ
theo kỳ tính thuế trước khi Nghị định này có hiệu lực thi hành thì không điều
chỉnh lại.
21. Các khoản chi của hoạt động kinh doanh: Ngân hàng, bảo hiểm, xổ số,
chứng khoán, hợp đồng BT, BOT, BTO và một số hoạt động kinh doanh đặc thù
khác không đúng hoặc vượt mức quy định của cơ quan có thẩm quyền.
a) Đối với chi phí trả lãi tiền vay của các hợp đồng BT, BOT, BTO:
a1) Doanh nghiệp BT, BOT, BTO được tính vào chi phí được trừ đối với
khoản chi trả lãi tiền vay của các hợp đồng BT, BOT, BTO theo thực tế phát sinh
trong kỳ. Trường hợp doanh nghiệp lựa chọn áp dụng phân bổ chi phí lãi vay của
các hợp đồng BT, BOT, BTO theo doanh thu thì chi phí lãi vay trong kỳ của các
hợp đồng BT, BOT, BTO được xác định theo công thức sau:
Chi phí lãi
vay trong kỳ
Tổng chi phí lãi vay theo
phương án tài chính
=
Tổng doanh thu theo
phương án tài chính
x
Doanh thu thực
hiện trong kỳ
a2) Trường hợp doanh nghiệp đã lựa chọn áp dụng chi phí trả lãi tiền vay phân
bổ theo doanh thu thì việc áp dụng phương pháp phân bổ chi phí trả lãi tiền vay
được áp dụng trong suốt thời gian thực hiện hợp đồng BT, BOT, BTO;
a3) Phần chi phí trả lãi tiền vay theo thực tế phát sinh trong kỳ của các hợp
đồng BT, BOT, BTO vượt mức chi phí lãi vay phân bổ theo doanh thu quy định tại
điểm này không được tính vào chi phí được trừ trong kỳ mà chuyển sang các kỳ
tính thuế tiếp theo;
a4) Trường hợp trong kỳ tính thuế doanh nghiệp phát sinh giao dịch liên kết thì
thực hiện theo quy định của pháp luật về quản lý thuế đối với doanh nghiệp có giao
dịch liên kết.
b) Các khoản chi của hoạt động kinh doanh ngân hàng, bảo hiểm, xổ số,
chứng khoán không đúng hoặc vượt mức quy định theo hướng dẫn của Bộ trưởng
Bộ Tài chính.
22. Khoản chi không tương ứng với doanh thu tính thuế, trừ các khoản chi quy
định tại điểm i khoản 2 Điều 9 của Nghị định này.
23. Khoản chi không đáp ứng điều kiện chi, nội dung chi theo quy định của
pháp luật chuyên ngành, bao gồm: Khoản chi cho làm thêm giờ vượt mức thời gian
quy định của pháp luật về lao động; khoản chi quảng cáo trong trường hợp quảng
cáo các sản phẩm, hàng hóa, dịch vụ bị cấm quảng cáo hoặc quảng cáo các sản
phẩm, hàng hóa, dịch vụ phải đăng ký với cơ quan có thẩm quyền nhưng doanh
nghiệp không thực hiện đăng ký quảng cáo theo quy định của pháp luật; khoản chi
phục vụ sản xuất, kinh doanh không đúng hoặc vượt mức chi theo quy định của
pháp luật chuyên ngành.$md$,$md$TNDN_ND320-2025_ChươngII$md$,10,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu11$md$,$md$TNDN_ND320-2025$md$,$md$Điều 11. Thuế suất$md$,$md$Thuế suất
1. Thuế suất thuế thu nhập doanh nghiệp là 20%, trừ trường hợp quy định tại
các khoản 2, 3 và 5 Điều này và đối tượng được ưu đãi về thuế suất quy định tại
Điều 19 Nghị định này.
2. Thuế suất 15% áp dụng đối với doanh nghiệp có tổng doanh thu năm không
quá 03 tỷ đồng.
3. Thuế suất 17% áp dụng đối với doanh nghiệp có tổng doanh thu năm từ trên
03 tỷ đồng đến không quá 50 tỷ đồng.
4. Tổng doanh thu làm căn cứ xác định doanh nghiệp thuộc đối tượng áp dụng
thuế suất 15% và 17% quy định tại khoản 2 và khoản 3 Điều này là tổng doanh thu
từ hoạt động bán hàng, cung cấp dịch vụ (không bao gồm các khoản giảm trừ
doanh thu), doanh thu từ hoạt động tài chính và thu nhập khác trên Phụ lục kết quả
hoạt động sản xuất kinh doanh kèm theo tờ khai quyết toán thuế thu nhập doanh
nghiệp của kỳ tính thuế năm trước liền kề.
a) Trường hợp doanh nghiệp có thời gian hoạt động của kỳ tính thuế năm trước
liền kề dưới 12 tháng thì tổng doanh thu kỳ tính thuế năm trước liền kề được xác
định bằng tổng doanh thu thực tế trong kỳ tính thuế đó chia cho số tháng doanh
nghiệp thực tế hoạt động sản xuất, kinh doanh trong kỳ tính thuế nhân với 12 tháng.
Trường hợp doanh nghiệp mới thành lập, doanh nghiệp chuyển đổi loại hình
doanh nghiệp, chuyển đổi hình thức sở hữu, hợp nhất, sáp nhập, chia, tách trong
tháng bất kỳ của kỳ tính thuế năm trước liền kề thì thời gian hoạt động được tính
đủ tháng;
b) Trường hợp doanh nghiệp mới thành lập trong kỳ tính thuế và dự kiến tổng
doanh thu trong kỳ tính thuế không quá 03 tỷ đồng hoặc không quá 50 tỷ đồng thì
doanh nghiệp xác định tạm nộp hàng quý tương ứng theo mức thuế suất 15%
hoặc 17%.
Kết thúc kỳ tính thuế, trường hợp tổng doanh thu thực tế trong kỳ tính thuế
như dự kiến quy định tại điểm này thì doanh nghiệp thực hiện kê khai, quyết toán
thuế thu nhập doanh nghiệp theo quy định. Trường hợp tổng doanh thu thực tế
không đáp ứng điều kiện để hưởng mức thuế suất tương ứng như dự kiến quy định
tại điểm này dẫn đến nộp thiếu so với số thuế phải tạm nộp theo quy định thì doanh
nghiệp nộp bổ sung số tiền thuế còn thiếu và tiền chậm nộp theo quy định của pháp
luật về quản lý thuế;
c) Thuế suất 15% và 17% quy định tại Điều này không áp dụng đối với doanh
nghiệp được thành lập theo quy định của pháp luật Việt Nam là công ty con hoặc
công ty có quan hệ liên kết mà doanh nghiệp trong quan hệ liên kết không phải là
doanh nghiệp đáp ứng điều kiện áp dụng thuế suất quy định tại khoản 2 và khoản 3
Điều này.
5. Thuế suất thuế thu nhập doanh nghiệp đối với một số trường hợp khác được
quy định như sau:
a) Đối với hoạt động tìm kiếm, thăm dò và khai thác dầu khí từ 25% đến 50%.
Căn cứ vào vị trí, điều kiện khai thác và trữ lượng mỏ, Thủ tướng Chính phủ quyết
định mức thuế suất cụ thể phù hợp với từng hợp đồng dầu khí;
b) Đối với hoạt động thăm dò, khai thác tài nguyên quý hiếm (bao gồm: Bạch
kim, vàng, bạc, thiếc, wonfram, antimoan, đá quý, đất hiếm và tài nguyên quý
hiếm khác theo quy định của pháp luật) là 50%. Trường hợp các mỏ có từ 70%
diện tích được giao trở lên ở địa bàn có điều kiện kinh tế - xã hội đặc biệt khó
khăn, thuế suất là 40%.$md$,$md$TNDN_ND320-2025_ChươngII$md$,11,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu12$md$,$md$TNDN_ND320-2025$md$,$md$Điều 12. Phương pháp tính thuế$md$,$md$Phương pháp tính thuế
1. Số thuế thu nhập doanh nghiệp phải nộp trong kỳ tính thuế được tính bằng
thu nhập tính thuế nhân với thuế suất, trừ trường hợp quy định tại các khoản 3, 4
và 5 Điều này.
2. Doanh nghiệp Việt Nam đầu tư ở nước ngoài có phát sinh thu nhập từ hoạt
động sản xuất, kinh doanh tại nước ngoài trong kỳ tính thuế thực hiện như sau đây:
a) Đối với các nước mà Việt Nam đã ký Hiệp định tránh đánh thuế hai lần thì
thực hiện theo quy định của Hiệp định;
b) Đối với các nước mà Việt Nam chưa ký Hiệp định tránh đánh thuế hai lần,
trường hợp thuế thu nhập doanh nghiệp (hoặc một loại thuế có bản chất tương tự
như thuế thu nhập doanh nghiệp) ở các nước mà doanh nghiệp đầu tư có mức thuế
suất thuế thu nhập doanh nghiệp thấp hơn thì thu phần chênh lệch so với số thuế
thu nhập doanh nghiệp tính theo Luật Thuế thu nhập doanh nghiệp của Việt Nam,
cụ thể như sau:
b1) Doanh nghiệp Việt Nam đầu tư ra nước ngoài có thu nhập từ hoạt động sản
xuất, kinh doanh tại nước ngoài, thực hiện kê khai và nộp thuế thu nhập doanh
nghiệp theo quy định của Luật Thuế thu nhập doanh nghiệp của Việt Nam, kể cả
trường hợp doanh nghiệp đang được hưởng ưu đãi miễn thuế, giảm thuế thu nhập
theo quy định của nước doanh nghiệp đầu tư. Mức thuế suất thuế thu nhập doanh
nghiệp để tính và kê khai thuế đối với các khoản thu nhập từ nước ngoài là 20%,
không áp dụng mức thuế suất ưu đãi (nếu có) mà doanh nghiệp Việt Nam đầu tư ra
nước ngoài đang được hưởng theo Luật Thuế thu nhập doanh nghiệp của Việt Nam;
b2) Trường hợp khoản thu nhập từ dự án đầu tư tại nước ngoài đã chịu thuế
thu nhập doanh nghiệp ở nước ngoài, khi tính thuế thu nhập doanh nghiệp phải nộp
tại Việt Nam, doanh nghiệp Việt Nam đầu tư ra nước ngoài được trừ số thuế đã
nộp ở nước ngoài hoặc đã được đối tác nước tiếp nhận đầu tư trả thay, nhưng số
thuế được trừ không vượt quá số thuế thu nhập tính theo quy định của Luật Thuế
thu nhập doanh nghiệp của Việt Nam. Số thuế thu nhập doanh nghiệp mà doanh
nghiệp Việt Nam đầu tư ra nước ngoài được miễn thuế, giảm thuế đối với phần lợi
nhuận được hưởng từ dự án đầu tư ở nước ngoài theo luật pháp của nước doanh
nghiệp đầu tư cũng được trừ khi xác định số thuế thu nhập doanh nghiệp phải nộp
tại Việt Nam;
b3) Trường hợp tại thời điểm doanh nghiệp kê khai và nộp thuế thu nhập
doanh nghiệp theo quy định của Luật Thuế thu nhập doanh nghiệp của Việt Nam
mà khoản thu nhập từ dự án đầu tư tại nước ngoài chưa nộp thuế thu nhập doanh
nghiệp ở nước ngoài thì sau khi nộp thuế ở nước ngoài, doanh nghiệp thực hiện
khai bổ sung hồ sơ khai thuế để điều chỉnh số thuế thu nhập doanh nghiệp đã nộp
tại Việt Nam (nếu có). Trường hợp phát sinh số thuế nộp thừa thì doanh nghiệp
được hoàn hoặc chuyển sang kỳ sau theo quy định của pháp luật về quản lý thuế;
b4) Trường hợp doanh nghiệp Việt Nam đầu tư ở nước ngoài có thu nhập từ
dự án đầu tư tại nước ngoài trong kỳ tính thuế mà không thực hiện kê khai và nộp
thuế đối với phần thu nhập này thì cơ quan thuế thực hiện ấn định thu nhập chịu
thuế từ hoạt động sản xuất, kinh doanh tại nước ngoài theo quy định của pháp luật
về quản lý thuế;
b5) Khoản thu nhập từ dự án đầu tư tại nước ngoài được kê khai vào quyết
toán thuế thu nhập doanh nghiệp của kỳ tính thuế phát sinh khoản thuế thu nhập
doanh nghiệp phải nộp ở nước ngoài. Khoản lãi, lỗ phát sinh từ dự án đầu tư ở
nước ngoài không được trừ vào số lỗ, lãi phát sinh trong nước của doanh nghiệp
khi tính thuế thu nhập doanh nghiệp.
Bộ trưởng Bộ Tài chính hướng dẫn cụ thể hồ sơ kê khai và nộp thuế của doanh
nghiệp Việt Nam đầu tư ra nước ngoài đối với khoản thu nhập từ dự án đầu tư tại
nước ngoài quy định tại khoản này;
c) Đối với doanh nghiệp là công ty mẹ có số thuế được phân bổ từ số thuế bổ
sung của đơn vị hợp thành chịu thuế suất thấp theo quy định tại khoản 11 Điều 5
Nghị quyết số 107/2023/QH15 ngày 29 tháng 11 năm 2023 của Quốc hội về việc
áp dụng thuế thu nhập doanh nghiệp bổ sung theo quy định chống xói mòn cơ sở
thuế toàn cầu và các văn bản hướng dẫn thì số thuế được phân bổ được trừ vào số
thuế thu nhập doanh nghiệp phải nộp theo pháp luật thuế thu nhập doanh nghiệp
của Việt Nam nhưng tổng số thuế được trừ quy định tại điểm b khoản này và điểm
này không vượt quá số thuế thu nhập tính theo quy định của Luật Thuế thu nhập
doanh nghiệp của Việt Nam.
Việc bù trừ quy định tại điểm này được thực hiện vào kỳ tính thuế mà doanh
nghiệp kê khai và nộp thuế theo quy định tại Nghị quyết số 107/2023/QH15.
3. Số thuế thu nhập doanh nghiệp phải nộp đối với doanh nghiệp nước ngoài
quy định tại các điểm b2, b3 và b4 khoản 1 Điều 2 của Nghị định này được tính
theo tỷ lệ % trên doanh thu tính thuế phát sinh tại Việt Nam, cụ thể như sau:
a) Dịch vụ: 5%, riêng dịch vụ quản lý nhà hàng, khách sạn, casino: 10%; trường
hợp cung ứng dịch vụ có gắn với hàng hóa thì hàng hóa được tính theo tỷ lệ 1%;
trường hợp không tách riêng được giá trị hàng hoá với giá trị dịch vụ: 2%;
b) Cung cấp và phân phối hàng hóa tại Việt Nam theo hình thức xuất khẩu, nhập
khẩu tại chỗ hoặc theo các điều khoản thương mại quốc tế (Incoterms): 1%; riêng
trường hợp các doanh nghiệp nước ngoài bán hàng hóa là nguyên liệu, vật tư, linh
kiện tại kho ngoại quan, khu phi thuế quan để nhập khẩu vào Việt Nam phục vụ sản
xuất hàng xuất khẩu, gia công hàng xuất khẩu theo hợp đồng, các doanh nghiệp
nước ngoài chỉ định doanh nghiệp chế xuất giao hàng hóa là nguyên liệu, vật tư, linh
kiện cho doanh nghiệp chế xuất khác để phục vụ sản xuất hàng xuất khẩu, gia công
hàng xuất khẩu theo hợp đồng không phải nộp thuế thu nhập doanh nghiệp;
c) Tiền bản quyền: 10%;
d) Cho thuê máy bay, trực thăng, tàu lượn (kể cả thuê động cơ, phụ tùng), tàu
biển: 2%;
đ) Cho thuê giàn khoan, máy móc, thiết bị, phương tiện vận tải (trừ quy định
tại điểm d khoản này): 5%;
e) Lãi tiền vay: 5%;
g) Chuyển nhượng chứng khoán; tái bảo hiểm ra nước ngoài: 0,1%;
h) Dịch vụ tài chính phái sinh: 2%;
i) Chuyển nhượng vốn (trừ trường hợp giao dịch tái cơ cấu sở hữu của các
công ty trong nội bộ tập đoàn không làm thay đổi công ty mẹ tối cao của các bên
tham gia có sở hữu trực tiếp, gián tiếp doanh nghiệp tại Việt Nam sau tái cơ cấu và
không phát sinh thu nhập): 2%;
k) Xây dựng, vận tải và hoạt động khác: 2%.
Doanh thu tính thuế được xác định theo quy định tại Điều 8 của Nghị định này.
Bộ trưởng Bộ Tài chính quy định chi tiết khoản này, bao gồm cả việc xác định
doanh thu tính thuế thu nhập doanh nghiệp đối với một số trường hợp cụ thể.
4. Doanh nghiệp có tổng doanh thu năm không quá 03 tỷ đồng quy định tại
Điều 11 của Nghị định này, trong trường hợp không xác định được chi phí, thu nhập
của hoạt động sản xuất, kinh doanh thì kê khai nộp thuế thu nhập doanh nghiệp theo
tỷ lệ phần trăm (%) trên doanh thu bán hàng hoá, dịch vụ, cụ thể như sau:
a) Phân phối, cung cấp hàng hóa: 0,3%;
b) Sản xuất, vận tải, dịch vụ có gắn với hàng hóa, xây dựng có bao thầu
nguyên vật liệu: 1,2%;
c) Dịch vụ (bao gồm cả lãi tiền gửi, lãi tiền cho vay), xây dựng không bao thầu
nguyên vật liệu: 1,5%. Riêng hoạt động cho thuê tài sản, đại lý bảo hiểm, đại lý xổ
số, đại lý bán hàng đa cấp: 4%;
d) Hoạt động cung cấp sản phẩm và dịch vụ nội dung thông tin số về giải trí,
trò chơi điện tử, phim số, ảnh số, nhạc số, quảng cáo số: 4%;
đ) Hoạt động khác: 0,5%.
5. Hợp tác xã, liên hiệp hợp tác xã được thành lập theo quy định của Luật Hợp
tác xã, đơn vị sự nghiệp và tổ chức khác quy định tại các điểm c, d và e khoản 1
Điều 2 của Nghị định này có hoạt động sản xuất, kinh doanh hàng hoá, dịch vụ có
thu nhập chịu thuế thu nhập doanh nghiệp (trừ thu nhập được miễn thuế quy định
tại Điều 4 của Nghị định này) mà các đơn vị này hạch toán được doanh thu nhưng
không xác định được chi phí, thu nhập của hoạt động sản xuất, kinh doanh thì kê
khai nộp thuế thu nhập doanh nghiệp tính theo tỷ lệ % trên doanh thu bán hàng
hoá, dịch vụ, cụ thể như sau:
a) Đối với dịch vụ (bao gồm cả lãi tiền gửi, lãi tiền cho vay): 5%. Riêng dịch
vụ trong lĩnh vực giáo dục, y tế, biểu diễn nghệ thuật: 2%;
b) Đối với sản xuất, kinh doanh hàng hoá: 1%;
c) Đối với hoạt động khác: 2%.
THU NHẬP TỪ CHUYỂN NHƯỢNG VỐN,
CHUYỂN NHƯỢNG CHỨNG KHOÁN$md$,$md$TNDN_ND320-2025_ChươngII$md$,12,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu13$md$,$md$TNDN_ND320-2025$md$,$md$Điều 13. Thu nhập từ chuyển nhượng vốn$md$,$md$Thu nhập từ chuyển nhượng vốn
1. Thu nhập từ chuyển nhượng vốn của doanh nghiệp là thu nhập có được từ
chuyển nhượng một phần hoặc toàn bộ số vốn của doanh nghiệp đã đầu tư cho một
hoặc nhiều tổ chức, cá nhân khác (bao gồm cả trường hợp bán doanh nghiệp,
chuyển nhượng quyền góp vốn và các hình thức chuyển nhượng vốn khác theo quy
định của pháp luật), chuyển nhượng cổ phần của công ty không phải là công ty đại
chúng, chuyển nhượng cổ phần của tổ chức không phải là tổ chức niêm yết, đăng
ký giao dịch theo quy định của pháp luật chứng khoán.
Thời điểm xác định thu nhập từ chuyển nhượng vốn là thời điểm chuyển quyền
sở hữu vốn.
a) Trường hợp doanh nghiệp bán toàn bộ công ty trách nhiệm hữu hạn một
thành viên do tổ chức làm chủ sở hữu dưới hình thức chuyển nhượng vốn có gắn
với bất động sản thì kê khai và nộp thuế thu nhập doanh nghiệp theo hoạt động
chuyển nhượng bất động sản;
b) Trường hợp doanh nghiệp có chuyển nhượng vốn không nhận bằng tiền mà
nhận bằng tài sản (bao gồm cổ phiếu, chứng chỉ quỹ), lợi ích vật chất khác có phát
sinh thu nhập thì phải chịu thuế thu nhập doanh nghiệp. Giá trị tài sản, cổ phiếu,
chứng chỉ quỹ và lợi ích vật chất khác được xác định theo giá bán của sản phẩm
trên thị trường tại thời điểm nhận tài sản;
c) Doanh nghiệp có thu nhập từ chuyển nhượng vốn thì khoản thu nhập này
được xác định là khoản thu nhập khác và kê khai vào thu nhập chịu thuế khi tính
thuế thu nhập doanh nghiệp.
2. Xác định thu nhập tính thuế từ chuyển nhượng vốn
Thu nhập tính thuế từ chuyển nhượng vốn được xác định bằng giá chuyển
nhượng trừ đi giá mua của phần vốn chuyển nhượng và chi phí chuyển nhượng.
a) Giá chuyển nhượng được xác định là tổng giá trị thực tế mà bên chuyển
nhượng thu được theo hợp đồng chuyển nhượng.
a1) Trường hợp hợp đồng chuyển nhượng vốn quy định việc thanh toán theo
hình thức trả góp, trả chậm thì doanh thu của hợp đồng chuyển nhượng không bao
gồm lãi trả góp, lãi trả chậm theo thời hạn quy định trong hợp đồng;
a2) Trường hợp hợp đồng chuyển nhượng không quy định giá thanh toán hoặc
cơ quan thuế có cơ sở để xác định giá thanh toán không phù hợp theo giá thị
trường, cơ quan thuế có quyền kiểm tra và ấn định giá chuyển nhượng. Doanh
nghiệp có chuyển nhượng một phần vốn góp trong doanh nghiệp mà giá chuyển
nhượng đối với phần vốn góp này không phù hợp theo giá thị trường thì cơ quan
thuế được ấn định lại toàn bộ giá trị của doanh nghiệp tại thời điểm chuyển
nhượng để xác định lại giá chuyển nhượng tương ứng với tỷ lệ phần vốn góp
chuyển nhượng;
a3) Doanh nghiệp có hoạt động chuyển nhượng vốn cho tổ chức, cá nhân thì
phần giá trị vốn chuyển nhượng theo hợp đồng chuyển nhượng có giá trị từ 05
triệu đồng trở lên phải có chứng từ thanh toán không dùng tiền mặt. Trường hợp
việc chuyển nhượng vốn không có chứng từ thanh toán không dùng tiền mặt thì cơ
quan thuế có quyền ấn định giá chuyển nhượng.
Việc ấn định giá chuyển nhượng quy định tại điểm này thực hiện theo quy định
của pháp luật về quản lý thuế;
b) Giá mua của phần vốn chuyển nhượng được xác định đối với từng trường
hợp như sau:
b1) Trường hợp là vốn góp thành lập doanh nghiệp thì giá mua là giá trị phần
vốn góp lũy kế đến thời điểm chuyển nhượng vốn trên cơ sở sổ sách, hồ sơ, chứng
từ kế toán và được các bên tham gia đầu tư vốn hoặc tham gia hợp đồng hợp tác
kinh doanh xác nhận hoặc kết quả kiểm toán của công ty kiểm toán độc lập đối với
doanh nghiệp 100% vốn nước ngoài;
b2) Trường hợp là phần vốn do mua lại thì giá mua là giá trị vốn tại thời điểm
mua. Giá mua được xác định căn cứ vào hợp đồng mua lại phần vốn góp, chứng từ
thanh toán;
b3) Trường hợp doanh nghiệp đủ điều kiện hạch toán kế toán bằng đồng
ngoại tệ và thực hiện theo đúng quy định của pháp luật về chế độ kế toán có
chuyển nhượng vốn góp bằng ngoại tệ thì giá chuyển nhượng và giá mua của
phần vốn chuyển nhượng được xác định bằng đồng ngoại tệ; trường hợp doanh
nghiệp hạch toán kế toán bằng đồng Việt Nam có chuyển nhượng vốn góp bằng
ngoại tệ thì giá chuyển nhượng phải được xác định bằng đồng Việt Nam theo
pháp luật về quản lý thuế;
c) Chi phí chuyển nhượng là các khoản chi thực tế liên quan trực tiếp đến việc
chuyển nhượng, có chứng từ, hóa đơn hợp pháp. Chi phí chuyển nhượng bao gồm:
Chi phí để làm các thủ tục pháp lý cần thiết cho việc chuyển nhượng; các khoản phí
và lệ phí phải nộp khi làm thủ tục chuyển nhượng; các chi phí giao dịch, đàm phán,
ký kết hợp đồng chuyển nhượng và các chi phí khác có chứng từ chứng minh.
Trường hợp chi phí chuyển nhượng phát sinh ở nước ngoài thì các chứng từ
gốc đó phải được một cơ quan công chứng hoặc kiểm toán độc lập của nước có chi
phí phát sinh xác nhận và chứng từ phải được dịch ra tiếng Việt (có xác nhận của
đại diện có thẩm quyền).$md$,$md$TNDN_ND320-2025_ChươngIII$md$,13,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu14$md$,$md$TNDN_ND320-2025$md$,$md$Điều 14. Thu nhập từ đầu tư chứng khoán$md$,$md$Thu nhập từ đầu tư chứng khoán
1. Thu nhập từ chuyển nhượng chứng khoán của doanh nghiệp là thu nhập có
được từ việc chuyển nhượng cổ phiếu, quyền mua cổ phiếu của công ty đại
chúng, tổ chức niêm yết, tổ chức đăng ký giao dịch, chuyển nhượng trái phiếu, tín
phiếu, chứng chỉ quỹ và các loại chứng khoán khác theo quy định của pháp luật
về chứng khoán.
a) Trường hợp doanh nghiệp thực hiện phát hành thêm cổ phiếu để huy động
vốn thì phần chênh lệch giữa giá phát hành và mệnh giá không tính vào thu nhập
chịu thuế để tính thuế thu nhập doanh nghiệp;
b) Trường hợp doanh nghiệp tiến hành chia, tách, hợp nhất, sáp nhập mà thực
hiện hoán đổi cổ phiếu tại thời điểm chia, tách, hợp nhất, sáp nhập nếu phát sinh
thu nhập thì phần thu nhập này phải chịu thuế thu nhập doanh nghiệp;
c) Trường hợp doanh nghiệp có chuyển nhượng chứng khoán không nhận bằng
tiền mà nhận bằng tài sản (bao gồm cổ phiếu, chứng chỉ quỹ), lợi ích vật chất khác
có phát sinh thu nhập thì phải chịu thuế thu nhập doanh nghiệp. Giá trị tài sản, cổ
phiếu, chứng chỉ quỹ và lợi ích vật chất khác được xác định theo giá bán của sản
phẩm trên thị trường tại thời điểm nhận tài sản;
d) Doanh nghiệp có thu nhập từ chuyển nhượng chứng khoán thì khoản thu
nhập này được xác định là khoản thu nhập khác và kê khai vào thu nhập chịu thuế
khi tính thuế thu nhập doanh nghiệp.
2. Xác định thu nhập tính thuế từ chuyển nhượng chứng khoán
Thu nhập tính thuế từ chuyển nhượng chứng khoán trong kỳ được xác định
bằng giá bán chứng khoán trừ đi giá mua của chứng khoán chuyển nhượng và các
chi phí liên quan đến việc chuyển nhượng.
a) Giá bán chứng khoán được xác định như sau:
a1) Đối với chứng khoán niêm yết và chứng khoán của công ty đại chúng chưa
niêm yết nhưng thực hiện đăng ký giao dịch tại Sở Giao dịch chứng khoán thì giá
bán chứng khoán là giá thực tế bán chứng khoán (là giá khớp lệnh hoặc giá thỏa
thuận) theo thông báo của Sở Giao dịch chứng khoán;
a2) Đối với chứng khoán của các công ty không thuộc các trường hợp nêu trên
thì giá bán chứng khoán là giá chuyển nhượng ghi trên hợp đồng chuyển nhượng;
b) Giá mua của chứng khoán được xác định như sau:
b1) Đối với chứng khoán niêm yết và chứng khoán của công ty đại chúng chưa
niêm yết nhưng thực hiện đăng ký giao dịch tại Sở Giao dịch chứng khoán thì giá
mua chứng khoán là giá thực mua chứng khoán (là giá khớp lệnh hoặc giá thỏa
thuận) theo thông báo của Sở Giao dịch chứng khoán;
b2) Đối với chứng khoán mua thông qua đấu giá thì giá mua chứng khoán là
mức giá ghi trên thông báo kết quả trúng đấu giá cổ phần của tổ chức thực hiện
đấu giá cổ phần và giấy nộp tiền;
b3) Đối với chứng khoán không thuộc các trường hợp nêu trên thì giá mua
chứng khoán là giá chuyển nhượng ghi trên hợp đồng chuyển nhượng;
c) Chi phí chuyển nhượng là các khoản chi thực tế liên quan trực tiếp đến việc
chuyển nhượng, có chứng từ, hóa đơn hợp pháp, bao gồm: Chi phí để làm các thủ
tục pháp lý cần thiết cho việc chuyển nhượng; các khoản phí và lệ phí theo quy
định của pháp luật về phí và lệ phí; các chi phí giao dịch, đàm phán, ký kết hợp
đồng chuyển nhượng và các chi phí khác có chứng từ chứng minh.
3. Quỹ đầu tư chứng khoán (trừ công ty đầu tư chứng khoán) không thuộc đối
tượng nộp thuế thu nhập doanh nghiệp. Công ty quản lý Quỹ đầu tư chứng khoán
khấu trừ thuế thu nhập doanh nghiệp phải nộp của tổ chức đầu tư (không phân biệt
tổ chức đầu tư trong nước hay tổ chức đầu tư nước ngoài) khi Quỹ đầu tư chứng
khoán chia lợi tức cho nhà đầu tư theo thuế suất 20%.
Lợi tức chịu thuế quy định tại khoản này không bao gồm phần lợi tức thuộc
diện được miễn thuế hoặc đã nộp thuế thu nhập doanh nghiệp theo quy định của
pháp luật.
THU NHẬP TỪ CHUYỂN NHƯỢNG BẤT ĐỘNG SẢN$md$,$md$TNDN_ND320-2025_ChươngIII$md$,14,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu15$md$,$md$TNDN_ND320-2025$md$,$md$Điều 15. Thu nhập từ chuyển nhượng bất động sản$md$,$md$Thu nhập từ chuyển nhượng bất động sản
Thu nhập từ hoạt động chuyển nhượng bất động sản bao gồm:
1. Thu nhập từ chuyển nhượng quyền sử dụng đất, chuyển nhượng quyền thuê
đất (bao gồm cả chuyển nhượng dự án gắn với chuyển nhượng quyền sử dụng đất,
quyền thuê đất theo quy định của pháp luật).
2. Thu nhập từ hoạt động cho thuê, cho thuê lại quyền sử dụng đất của doanh
nghiệp kinh doanh bất động sản theo quy định của pháp luật về đất đai không phân
biệt có hay không có kết cấu hạ tầng, công trình kiến trúc gắn liền với đất.
Thu nhập từ hoạt động cho thuê, cho thuê lại quyền sử dụng đất quy định tại
khoản này không bao gồm trường hợp doanh nghiệp có hoạt động cho thuê nhà, cơ
sở hạ tầng, công trình kiến trúc trên đất nhưng không có quyền cho thuê, cho thuê
lại quyền sử dụng đất theo quy định của pháp luật về đất đai.
3. Thu nhập từ chuyển nhượng nhà, công trình xây dựng gắn liền với đất, kể cả
các tài sản gắn liền với nhà, công trình xây dựng đó nếu không tách riêng giá trị tài
sản khi chuyển nhượng không phân biệt có hay không có chuyển nhượng quyền sử
dụng đất, chuyển nhượng quyền thuê đất.
4. Thu nhập từ chuyển nhượng các tài sản gắn liền với đất.
5. Thu nhập từ chuyển nhượng quyền sở hữu nhà ở, cơ sở hạ tầng, công trình
kiến trúc trên đất.
6. Thu nhập từ chuyển nhượng, cho thuê bất động sản của Quỹ đầu tư bất động
sản theo quy định của pháp luật.
Công ty quản lý Quỹ đầu tư chứng khoán kê khai và nộp thuế đối với thu nhập
từ chuyển nhượng, cho thuê bất động sản quy định tại khoản này.$md$,$md$TNDN_ND320-2025_ChươngIV$md$,15,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu16$md$,$md$TNDN_ND320-2025$md$,$md$Điều 16. Căn cứ tính thuế$md$,$md$Căn cứ tính thuế
1. Căn cứ tính thuế thu nhập từ chuyển nhượng bất động sản là thu nhập tính
thuế và thuế suất.
2. Thu nhập tính thuế được xác định bằng thu nhập chịu thuế từ chuyển
nhượng bất động sản trừ đi các khoản lỗ của hoạt động chuyển nhượng bất động
sản được chuyển lỗ theo quy định (nếu có).
3. Thu nhập chịu thuế từ chuyển nhượng bất động sản được xác định bằng
doanh thu từ hoạt động chuyển nhượng bất động sản trừ đi chi phí được trừ từ hoạt
động chuyển nhượng bất động sản (bao gồm: Giá vốn của bất động sản và các
khoản chi phí được trừ liên quan đến hoạt động chuyển nhượng bất động sản) quy
định tại Điều 17 của Nghị định này.
4. Thuế suất thuế thu nhập doanh nghiệp đối với hoạt động chuyển nhượng bất
động sản là 20%.
5. Số thuế thu nhập doanh nghiệp trong kỳ tính thuế đối với hoạt động chuyển
nhượng bất động sản bằng thu nhập tính thuế từ hoạt động chuyển nhượng bất
động sản nhân với thuế suất 20%.
6. Trường hợp tổ chức tín dụng, tổ chức mà Nhà nước sở hữu 100% vốn điều
lệ do Chính phủ thành lập có chức năng mua, bán, xử lý nợ nhận giá trị bất động
sản và tài sản khác là tài sản bảo đảm tiền vay để thay thế cho việc thực hiện nghĩa
vụ được bảo đảm thì tổ chức tín dụng, tổ chức mà Nhà nước sở hữu 100% vốn điều
lệ do Chính phủ thành lập có chức năng mua, bán, xử lý nợ khi được phép chuyển
nhượng bất động sản, tài sản khác theo quy định của pháp luật phải kê khai nộp
thuế từ hoạt động chuyển nhượng bất động sản, tài sản khác vào ngân sách nhà
nước. Trường hợp bán đấu giá bất động sản, tài sản khác là tài sản bảo đảm tiền
vay thì số tiền thu được thực hiện thanh toán theo quy định của pháp luật về bảo
đảm tiền vay và kê khai, nộp thuế theo quy định. Sau khi thanh toán các khoản
trên, số tiền còn lại được trả cho các tổ chức kinh doanh đã thế chấp bất động sản,
tài sản khác để bảo đảm tiền vay.
Trường hợp tổ chức tín dụng, tổ chức mà Nhà nước sở hữu 100% vốn điều lệ
do Chính phủ thành lập có chức năng mua, bán, xử lý nợ được phép chuyển
nhượng bất động sản, tài sản khác đã được thế chấp theo quy định của pháp luật để
thu hồi vốn nếu không xác định được giá vốn của bất động sản, tài sản khác thì giá
vốn được xác định bằng vốn vay phải trả theo hợp đồng thế chấp bất động sản, tài
sản khác cộng với chi phí lãi vay chưa trả đến thời điểm phát mãi bất động sản, tài
sản khác thế chấp theo hợp đồng và các khoản chi phí phát sinh khi chuyển
nhượng bất động sản, tài sản khác nếu có hóa đơn, chứng từ hợp pháp.
7. Trường hợp cơ quan thi hành án hoặc tổ chức có thẩm quyền bán đấu giá bất
động sản, tài sản khác là tài sản bảo đảm thi hành án thì số tiền thu được thực hiện
theo quy định của pháp luật về kê biên, đấu giá để bảo đảm thi hành án. Tổ chức
bán đấu giá bất động sản, tài sản khác thực hiện kê khai, khấu trừ tiền thuế từ
chuyển nhượng bất động sản, tài sản khác nộp vào ngân sách nhà nước. Trên các
chứng từ ghi rõ kê khai, nộp thuế về bán tài sản đảm bảo thi hành án.
Trường hợp cơ quan thi hành án hoặc tổ chức có thẩm quyền chuyển nhượng
bất động sản, tài sản khác là tài sản đảm bảo thi hành án nếu không xác định được
giá vốn của bất động sản, tài sản khác thì giá vốn được xác định bằng số tiền nợ
phải trả nợ theo quyết định của Tòa án hoặc cơ quan có thẩm quyền để thi hành án
cộng với các khoản chi phí phát sinh khi chuyển nhượng bất động sản, tài sản khác
nếu có hóa đơn chứng từ hợp pháp.$md$,$md$TNDN_ND320-2025_ChươngIV$md$,16,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu17$md$,$md$TNDN_ND320-2025$md$,$md$Điều 17. Doanh thu, chi phí được trừ từ hoạt động chuyển nhượng bất$md$,$md$Doanh thu, chi phí được trừ từ hoạt động chuyển nhượng bất
động sản
1. Doanh thu từ hoạt động chuyển nhượng bất động sản
a) Doanh thu từ hoạt động chuyển nhượng bất động sản được xác định theo giá
thực tế chuyển nhượng bất động sản theo hợp đồng chuyển nhượng, mua bán bất
động sản phù hợp với quy định của pháp luật (bao gồm cả các khoản phụ thu và
phí thu thêm nếu có).
Trường hợp giá chuyển quyền sử dụng đất theo hợp đồng chuyển nhượng, mua
bán bất động sản thấp hơn giá đất tại bảng giá đất do Ủy ban nhân dân tỉnh, thành
phố trực thuộc Trung ương quy định tại thời điểm ký hợp đồng chuyển nhượng bất
động sản thì tính theo giá đất do Ủy ban nhân dân tỉnh, thành phố trực thuộc Trung
ương quy định tại thời điểm ký hợp đồng chuyển nhượng bất động sản;
b) Thời điểm xác định doanh thu tính thuế là thời điểm bên bán bàn giao bất
động sản cho bên mua, không phụ thuộc việc bên mua đã đăng ký quyền sở hữu
tài sản, quyền sử dụng đất, xác lập quyền sử dụng đất tại cơ quan nhà nước có
thẩm quyền;
c) Trường hợp doanh nghiệp thực hiện dự án đầu tư cơ sở hạ tầng, nhà để
chuyển nhượng hoặc cho thuê, có thu tiền ứng trước của khách hàng theo tiến độ
dưới mọi hình thức thì thời điểm xác định doanh thu tính thuế thu nhập doanh
nghiệp tạm nộp là thời điểm thu tiền của khách hàng, cụ thể:
c1) Trường hợp doanh nghiệp có thu tiền của khách hàng mà xác định được
chi phí tương ứng với doanh thu đã ghi nhận (bao gồm cả chi phí trích trước của
phần dự toán hạng mục công trình chưa hoàn thành tương ứng với doanh thu đã
ghi nhận) thì doanh nghiệp kê khai, nộp thuế thu nhập doanh nghiệp theo doanh
thu trừ chi phí;
c2) Trường hợp doanh nghiệp có thu tiền của khách hàng mà chưa xác định
được chi phí tương ứng với doanh thu thì doanh nghiệp kê khai tạm nộp thuế thu
nhập doanh nghiệp theo tỷ lệ 1% trên doanh thu thu được tiền (không bao gồm
thuế giá trị gia tăng) và doanh thu này chưa phải tính vào doanh thu tính thuế thu
nhập doanh nghiệp trong năm;
c3) Khi bàn giao bất động sản doanh nghiệp phải thực hiện quyết toán thuế thu
nhập doanh nghiệp và quyết toán lại số thuế thu nhập doanh nghiệp phải nộp.
Trường hợp số thuế thu nhập doanh nghiệp đã tạm nộp thấp hơn số thuế thu nhập
doanh nghiệp phải nộp thì doanh nghiệp phải nộp đủ số thuế còn thiếu vào ngân
sách nhà nước. Trường hợp số thuế thu nhập doanh nghiệp đã tạm nộp lớn hơn số
thuế phải nộp thì doanh nghiệp được trừ số thuế nộp thừa vào số thuế thu nhập
doanh nghiệp phải nộp của kỳ tiếp theo hoặc được hoàn lại số thuế đã nộp thừa;
c4) Đối với doanh nghiệp kinh doanh bất động sản có thu tiền ứng trước của
khách hàng theo tiến độ và kê khai tạm nộp thuế theo tỷ lệ % trên doanh thu thu
được tiền, doanh thu này chưa phải tính vào doanh thu tính thuế thu nhập doanh
nghiệp trong năm đồng thời có phát sinh chi phí quảng cáo, tiếp thị, khuyến mại,
hoa hồng môi giới khi bắt đầu chào bán vào năm phát sinh doanh thu thu tiền theo
tiến độ thì chưa tính các khoản chi phí này vào năm phát sinh chi phí. Các khoản
chi phí quảng cáo, tiếp thị, khuyến mại, hoa hồng môi giới này được tính vào chi
phí được trừ tại năm đầu tiên bàn giao bất động sản, phát sinh doanh thu tính thuế
thu nhập doanh nghiệp;
d) Doanh thu để tính thu nhập chịu thuế trong một số trường hợp được xác
định như sau:
d1) Trường hợp doanh nghiệp có cho thuê lại đất thì doanh thu để tính thu
nhập chịu thuế là số tiền bên thuê trả từng kỳ theo hợp đồng thuê. Trường hợp bên
thuê trả tiền thuê trước cho nhiều năm thì doanh thu để tính thu nhập chịu thuế
được phân bổ đều cho số năm trả tiền trước hoặc được xác định theo doanh thu trả
tiền một lần. Việc chọn hình thức doanh thu trả tiền một lần chỉ được xác định khi
doanh nghiệp đã đảm bảo hoàn thành các trách nhiệm tài chính đối với Nhà nước,
đảm bảo các nghĩa vụ đối với các bên thuê lại đất cho hết thời hạn cho thuê lại đất.
Trường hợp doanh nghiệp đang trong thời gian hưởng ưu đãi thuế thu nhập
doanh nghiệp lựa chọn phương pháp xác định doanh thu để tính thu nhập chịu thuế
là toàn bộ số tiền thuê bên thuê trả trước cho nhiều năm thì việc xác định số thuế thu
nhập doanh nghiệp từng năm miễn thuế, giảm thuế căn cứ vào tổng số thuế thu nhập
doanh nghiệp của số năm trả tiền trước chia cho số năm bên thuê trả tiền trước;
d2) Trường hợp tổ chức tín dụng nhận giá trị quyền sử dụng đất bảo đảm tiền
vay để thay thế cho việc thực hiện nghĩa vụ được bảo đảm nếu có chuyển quyền sử
dụng đất là tài sản thế chấp bảo đảm tiền vay thì doanh thu để tính thu nhập chịu
thuế là giá chuyển nhượng quyền sử dụng đất do các bên thỏa thuận;
d3) Trường hợp chuyển quyền sử dụng đất là tài sản kê biên bảo đảm thi hành
án thì doanh thu để tính thu nhập chịu thuế là giá chuyển nhượng quyền sử dụng
đất do các bên đương sự thỏa thuận hoặc giá do Hội đồng định giá xác định.
Việc xác định doanh thu đối với các trường hợp nêu tại điểm d phải đảm bảo
các nguyên tắc nêu tại các điểm a, b và c khoản này.
2. Chi phí được trừ từ hoạt động chuyển nhượng bất động sản
Các khoản chi được trừ để xác định thu nhập chịu thuế của hoạt động chuyển
nhượng bất động sản trong kỳ tính thuế phải tương ứng với doanh thu để tính thu
nhập chịu thuế và phải đảm bảo các điều kiện của các khoản chi được trừ quy định
tại Điều 9 của Nghị định này và không thuộc các khoản chi không được trừ quy
định tại Điều 10 của Nghị định này. Chi phí chuyển nhượng bất động sản được trừ
bao gồm:
a) Giá vốn của đất chuyển quyền được xác định phù hợp với nguồn gốc quyền
sử dụng đất, cụ thể như sau:
a1) Đối với đất Nhà nước giao có thu tiền sử dụng đất, thu tiền cho thuê đất thì
giá vốn là số tiền sử dụng đất, số tiền cho thuê đất thực nộp ngân sách nhà nước;
a2) Đối với đất nhận quyền sử dụng của tổ chức, cá nhân khác thì căn cứ vào
hợp đồng và chứng từ trả tiền hợp pháp khi nhận quyền sử dụng đất, quyền thuê
đất; trường hợp không có hợp đồng và chứng từ trả tiền hợp pháp thì giá vốn được
tính theo giá đất tại bảng giá đất do Ủy ban nhân dân cấp tỉnh quy định (trước ngày
01 tháng 01 năm 2026) hoặc Hội đồng nhân dân cấp tỉnh quyết định (kể từ ngày 01
tháng 01 năm 2026) tại thời điểm doanh nghiệp nhận chuyển nhượng bất động sản;
a3) Trường hợp đất của doanh nghiệp được thừa kế, cho, biếu, tặng trước năm
1994 thì giá vốn được xác định theo giá các loại đất do Ủy ban nhân dân tỉnh,
thành phố trực thuộc Trung ương quyết định năm 1994 căn cứ vào Bảng khung
giá các loại đất quy định tại Nghị định số 87-CP ngày 17 tháng 8 năm 1994 của
Chính phủ;
a4) Đối với đất có nguồn gốc do góp vốn thì giá vốn là giá trị quyền sử dụng
đất, quyền thuê đất theo biên bản định giá tài sản khi góp vốn;
a5) Trường hợp doanh nghiệp đổi công trình lấy đất của Nhà nước thì giá vốn
được xác định theo giá trị công trình đã đổi, trừ trường hợp thực hiện theo quy
định riêng của cơ quan nhà nước có thẩm quyền;
a6) Giá trúng đấu giá trong trường hợp đấu giá quyền sử dụng đất, quyền thuê đất;
a7) Đối với đất của doanh nghiệp có nguồn gốc do thừa kế theo pháp luật dân
sự, do được cho, biếu, tặng mà không xác định được giá vốn thì được tính theo
bảng giá đất do Ủy ban nhân dân cấp tỉnh quy định (trước ngày 01 tháng 01 năm
2026) hoặc Hội đồng nhân dân cấp tỉnh quyết định (kể từ ngày 01 tháng 01 năm
2026) tại thời điểm thừa kế, cho, biếu, tặng;
a8) Đối với đất thế chấp bảo đảm tiền vay, đất là tài sản kê biên để bảo đảm thi
hành án thì giá vốn đất được xác định tùy theo từng trường hợp cụ thể theo hướng
dẫn nêu trên.
Đối với các trường hợp quy định tại điểm a khoản này, trường hợp được cơ
quan nhà nước có thẩm quyền cho phép chuyển mục đích sử dụng đất theo quy
định của pháp luật về đất đai thì giá vốn bao gồm cả số tiền sử dụng đất, tiền thuê
đất nộp ngân sách nhà nước theo quy định của pháp luật về đất đai khi chuyển mục
đích sử dụng đất;
b) Chi phí bồi thường, hỗ trợ, tái định cư do doanh nghiệp tự nguyện ứng trước
theo phương án bồi thường tái định cư đã được cơ quan nhà nước có thẩm quyền
phê duyệt theo quy định của pháp luật về đất đai.
Hồ sơ, chứng từ của các khoản chi phí bồi thường, hỗ trợ, tái định cư thực hiện
theo quy định của pháp luật về đất đai;
c) Các loại phí, lệ phí theo quy định của pháp luật liên quan đến cấp quyền sử
dụng đất;
d) Chi phí cải tạo đất, san lấp mặt bằng;
đ) Chi phí đầu tư xây dựng kết cấu hạ tầng như đường giao thông, điện, cấp
nước, thoát nước, bưu chính viễn thông;
e) Giá trị kết cấu hạ tầng, công trình kiến trúc có trên đất;
g) Các khoản chi phí khác liên quan đến bất động sản được chuyển nhượng;
h) Trường hợp doanh nghiệp vừa có hoạt động kinh doanh bất động sản vừa có
hoạt động kinh doanh được hưởng ưu đãi thuế thì phải hạch toán riêng các khoản
chi phí. Trường hợp không hạch toán riêng được chi phí của từng hoạt động thì chi
phí chung được phân bổ theo tỷ lệ giữa doanh thu từ chuyển nhượng bất động sản
so với tổng doanh thu của doanh nghiệp;
i) Không được tính vào chi phí chuyển nhượng bất động sản các khoản chi phí
đã được Nhà nước thanh toán hoặc thanh toán bằng nguồn vốn khác.
3. Trường hợp dự án đầu tư hoàn thành từng phần và chuyển nhượng dần theo
tiến độ hoàn thành thì các khoản chi phí chung sử dụng cho dự án, chi phí trực tiếp
sử dụng cho phần dự án đã hoàn thành được phân bổ theo m2 đất chuyển quyền để
xác định thu nhập chịu thuế của diện tích đất chuyển quyền; bao gồm: Chi phí
đường giao thông nội bộ; khuôn viên cây xanh; chi phí đầu tư xây dựng hệ thống
cấp, thoát nước; trạm biến thế điện; chi phí bồi thường về tài sản trên đất; chi phí
bồi thường, hỗ trợ, tái định cư và kinh phí tổ chức thực hiện bồi thường giải phóng
mặt bằng được cấp có thẩm quyền phê duyệt còn lại chưa được trừ vào tiền sử
dụng đất, tiền thuê đất theo quy định; các chi phí khác đầu tư trên đất liên quan đến
chuyển quyền sử dụng đất, chuyển quyền thuê đất.
a) Việc phân bổ các chi phí trên được thực hiện theo công thức sau:
Chi phí phân
bổ cho diện
tích đất đã
chuyển nhượng
=
Tổng chi phí đầu tư kết cấu hạ tầng
x Diện tích đất đã
chuyển nhượng
Tổng diện tích đất được giao dự
án (trừ diện tích đất sử dụng vào
mục đích công cộng theo quy
định của pháp luật về đất đai)
b) Trường hợp một phần diện tích của dự án không chuyển nhượng được sử
dụng vào hoạt động kinh doanh khác thì các khoản chi phí chung nêu trên cũng
phân bổ cho cả phần diện tích này để theo dõi, hạch toán, kê khai nộp thuế thu
nhập doanh nghiệp đối với hoạt động kinh doanh khác;
c) Trường hợp doanh nghiệp có hoạt động đầu tư xây dựng cơ sở hạ tầng kéo
dài trong nhiều năm và chỉ quyết toán giá trị kết cấu hạ tầng khi toàn bộ công việc
hoàn tất thì khi tổng hợp chi phí chuyển nhượng bất động sản cho phần diện tích đất
đã chuyển quyền, doanh nghiệp được tạm phân bổ chi phí đầu tư kết cấu hạ tầng
thực tế đã phát sinh theo tỷ lệ diện tích đất đã chuyển quyền theo công thức quy định
tại điểm a khoản này và trích trước các khoản chi phí đầu tư xây dựng cơ sở hạ tầng
tương ứng với doanh thu đã ghi nhận khi xác định thu nhập chịu thuế. Sau khi hoàn
tất quá trình đầu tư xây dựng, doanh nghiệp tính toán, điều chỉnh lại phần chi phí
đầu tư kết cấu hạ tầng đã tạm phân bổ và trích trước cho phần diện tích đã chuyển
quyền cho phù hợp với tổng giá trị kết cấu hạ tầng. Trường hợp khi điều chỉnh lại
phát sinh số thuế nộp thừa so với số thuế thu nhập từ chuyển nhượng bất động sản
phải nộp thì doanh nghiệp được trừ số thuế nộp thừa vào số thuế phải nộp của kỳ
tính thuế tiếp theo hoặc được hoàn trả theo quy định; nếu số thuế đã nộp chưa đủ thì
doanh nghiệp có trách nhiệm nộp đủ số thuế còn thiếu theo quy định.
ƯU ĐÃI THUẾ THU NHẬP DOANH NGHIỆP$md$,$md$TNDN_ND320-2025_ChươngIV$md$,17,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu18$md$,$md$TNDN_ND320-2025$md$,$md$Điều 18. Nguyên tắc, đối tượng áp dụng ưu đãi thuế thu nhập doanh nghiệp$md$,$md$Nguyên tắc, đối tượng áp dụng ưu đãi thuế thu nhập doanh nghiệp
1. Doanh nghiệp được hưởng ưu đãi thuế thu nhập doanh nghiệp theo ngành,
nghề ưu đãi thuế thu nhập doanh nghiệp, địa bàn ưu đãi thuế thu nhập doanh
nghiệp quy định tại Điều này. Mức ưu đãi thuế thu nhập doanh nghiệp thực hiện
theo quy định tại Điều 19 và Điều 20 của Nghị định này.
Trường hợp Nghị định khác của Chính phủ có quy định về ưu đãi thuế thu
nhập doanh nghiệp khác với quy định của Nghị định này thì thực hiện theo quy
định của Nghị định này, trừ Nghị định quy định chi tiết Luật Thủ đô, Nghị định
được ban hành theo quy định tại điểm c khoản 1 Điều 14 Luật Ban hành văn bản
quy phạm pháp luật và điểm h khoản 8 Điều 10 Luật Tổ chức Chính phủ, các văn
bản hướng dẫn các Nghị quyết quy định cơ chế, chính sách đặc biệt, đặc thù của
Quốc hội và các Nghị quyết của Chính phủ, Nghị quyết của Ủy ban Thường vụ
Quốc hội quy định các trường hợp tại khoản 2 và khoản 3 Điều 4 của Nghị quyết
số 206/2025/QH15 ngày 24 tháng 6 năm 2025 của Quốc hội về cơ chế đặc biệt xử
lý khó khăn, vướng mắc do quy định của pháp luật.
2. Ngành, nghề ưu đãi thuế thu nhập doanh nghiệp bao gồm các trường hợp sau:
a) Ứng dụng công nghệ cao, đầu tư mạo hiểm cho phát triển công nghệ cao
thuộc danh mục công nghệ cao được ưu tiên đầu tư phát triển theo quy định của
Luật Công nghệ cao; ứng dụng công nghệ chiến lược theo quy định của pháp luật
về khoa học, công nghệ và đổi mới sáng tạo; ươm tạo công nghệ cao, ươm tạo
doanh nghiệp công nghệ cao; đầu tư xây dựng - kinh doanh cơ sở ươm tạo công
nghệ cao, ươm tạo doanh nghiệp công nghệ cao;
b) Sản xuất sản phẩm phần mềm; sản xuất sản phẩm an toàn thông tin mạng và
cung cấp dịch vụ an toàn thông tin mạng đảm bảo các điều kiện theo quy định của
pháp luật về an toàn thông tin mạng; sản xuất sản phẩm, cung cấp dịch vụ công
nghệ số trọng điểm, sản xuất thiết bị điện tử theo quy định của pháp luật về công
nghiệp công nghệ số; nghiên cứu và phát triển, thiết kế, sản xuất, đóng gói, kiểm
thử sản phẩm chip bán dẫn; xây dựng trung tâm dữ liệu trí tuệ nhân tạo theo quy
định của pháp luật về công nghiệp công nghệ số;
c) Sản xuất sản phẩm công nghiệp hỗ trợ thuộc Danh mục sản phẩm công
nghiệp hỗ trợ ưu tiên phát triển do Chính phủ quy định đáp ứng một trong các tiêu
chí sau đây:
c1) Sản phẩm công nghiệp hỗ trợ cho công nghệ cao theo quy định của Luật
Công nghệ cao;
c2) Sản phẩm công nghiệp hỗ trợ cho sản xuất sản phẩm các ngành dệt - may,
da - giầy, điện tử - tin học (bao gồm cả thiết kế, sản xuất bán dẫn), sản xuất lắp ráp
ô tô, cơ khí chế tạo đến ngày Luật Thuế thu nhập doanh nghiệp có hiệu lực thi
hành (ngày 01 tháng 10 năm 2025) mà trong nước chưa sản xuất được hoặc đã sản
xuất được nhưng phải đáp ứng tiêu chuẩn kỹ thuật của Liên minh Châu Âu hoặc
tương đương (nếu có) theo hướng dẫn của Bộ trưởng Bộ Công Thương;
d) Sản xuất năng lượng tái tạo, năng lượng sạch, năng lượng từ việc tiêu hủy
chất thải; bảo vệ môi trường; sản xuất vật liệu composit, các loại vật liệu xây dựng
nhẹ, vật liệu quý hiếm; sản xuất quốc phòng, an ninh và sản xuất sản phẩm động
viên công nghiệp theo quy định của pháp luật về công nghiệp quốc phòng, an ninh
và động viên công nghiệp; sản xuất sản phẩm công nghiệp hóa chất trọng điểm và
sản phẩm cơ khí trọng điểm theo quy định của pháp luật về hóa chất, pháp luật về
cơ khí;
đ) Đầu tư phát triển nhà máy nước, nhà máy điện, hệ thống cấp thoát nước,
cầu, đường bộ, đường sắt, cảng hàng không, cảng biển, cảng sông, sân bay, nhà ga
và công trình cơ sở hạ tầng đặc biệt quan trọng khác do Thủ tướng Chính phủ
quyết định;
e) Doanh nghiệp công nghệ cao, doanh nghiệp nông nghiệp ứng dụng công
nghệ cao theo quy định của Luật Công nghệ cao; doanh nghiệp khoa học và công
nghệ theo quy định của Luật Khoa học, công nghệ và đổi mới sáng tạo;
g) Dự án đầu tư trong lĩnh vực sản xuất đáp ứng các điều kiện sau đây:
g1) Có quy mô vốn đầu tư tối thiểu 12.000 tỷ đồng và thực hiện giải ngân tổng
vốn đầu tư đăng ký không quá 05 năm kể từ ngày được phép đầu tư theo quy định
của pháp luật về đầu tư;
g2) Sử dụng công nghệ đáp ứng yêu cầu theo quy định của Bộ trưởng Bộ Khoa
học và Công nghệ;
h) Dự án đầu tư thuộc đối tượng ưu đãi và hỗ trợ đầu tư đặc biệt quy định tại
khoản 2 Điều 20 Luật Đầu tư.
Thời gian giải ngân tổng vốn đầu tư của các dự án quy định tại điểm này
không quá 10 năm kể từ thời điểm cấp Giấy chứng nhận đầu tư hoặc được phép
đầu tư theo quy định của pháp luật về đầu tư;
i) Trồng, chăm sóc, bảo vệ rừng; sản xuất, nhân và lai tạo giống cây trồng, vật
nuôi; đầu tư bảo quản nông sản sau thu hoạch, bảo quản nông sản, thủy sản và thực
phẩm; sản xuất, khai thác và tinh chế muối, trừ sản xuất muối quy định tại khoản 1
Điều 4 của Nghị định này;
k) Nuôi trồng lâm sản;
l) Sản phẩm cây trồng, rừng trồng, chăn nuôi, thủy sản nuôi trồng, chế biến
nông sản, thủy sản.
Thu nhập từ chế biến nông sản, thủy sản quy định tại điểm này phải đáp ứng
các điều kiện quy định tại điểm b1 và điểm b2 khoản 1 Điều 4 của Nghị định này;
m) Sản xuất thép cao cấp; sản xuất sản phẩm tiết kiệm năng lượng; sản xuất
máy móc, thiết bị phục vụ cho sản xuất nông nghiệp, lâm nghiệp, ngư nghiệp,
diêm nghiệp; sản xuất thiết bị tưới tiêu; sản xuất thức ăn gia súc, gia cầm, thủy sản;
n) Sản xuất, lắp ráp ô tô; sản xuất sản phẩm công nghệ số khác;
o) Đầu tư kinh doanh cơ sở kỹ thuật hỗ trợ doanh nghiệp nhỏ và vừa, cơ sở
ươm tạo doanh nghiệp nhỏ và vừa; đầu tư kinh doanh khu làm việc chung hỗ trợ
doanh nghiệp nhỏ và vừa khởi nghiệp sáng tạo theo quy định của Luật Hỗ trợ
doanh nghiệp nhỏ và vừa;
p) Quỹ tín dụng nhân dân, tổ chức tài chính vi mô, ngân hàng hợp tác xã;
q) Hợp tác xã, liên hiệp hợp tác xã hoạt động trong lĩnh vực nông nghiệp, lâm
nghiệp, ngư nghiệp, diêm nghiệp;
r) Xã hội hóa trong các lĩnh vực giáo dục - đào tạo, dạy nghề, y tế, văn hóa, thể
thao, môi trường theo Danh mục loại hình, tiêu chí quy mô, tiêu chuẩn do Thủ
tướng Chính phủ quy định; giám định tư pháp;
s) Đầu tư xây dựng nhà ở xã hội để bán, cho thuê, cho thuê mua đối với các
đối tượng quy định tại Luật Nhà ở;
t) Xuất bản theo quy định của Luật Xuất bản;
u) Báo chí (bao gồm cả quảng cáo trên báo) theo quy định của Luật Báo chí.
3. Địa bàn ưu đãi thuế thu nhập doanh nghiệp bao gồm:
a) Địa bàn có điều kiện kinh tế - xã hội đặc biệt khó khăn theo quy định của
pháp luật về đầu tư, trừ địa bàn có điều kiện kinh tế - xã hội đặc biệt khó khăn quy
định tại số thứ tự 55 Phụ lục III danh mục địa bàn ưu đãi đầu tư ban hành kèm theo
Nghị định số 31/2021/NĐ-CP ngày 26 tháng 3 năm 2021 của Chính phủ (được sửa
đổi, bổ sung tại khoản 37 Điều 1 Nghị định số 239/2025/NĐ-CP ngày 03 tháng 9
năm 2025 của Chính phủ);
b) Địa bàn có điều kiện kinh tế - xã hội khó khăn theo quy định của pháp luật
về đầu tư, trừ địa bàn có điều kiện kinh tế - xã hội khó khăn quy định tại số thứ tự
55 Phụ lục III danh mục địa bàn ưu đãi đầu tư ban hành kèm theo Nghị định số
31/2021/NĐ-CP ngày 26 tháng 3 năm 2021 của Chính phủ (được sửa đổi, bổ sung
tại khoản 37 Điều 1 Nghị định số 239/2025/NĐ-CP ngày 03 tháng 9 năm 2025 của
Chính phủ);
c) Khu kinh tế, khu công nghệ cao, khu nông nghiệp ứng dụng công nghệ cao,
khu công nghệ số tập trung.$md$,$md$TNDN_ND320-2025_ChươngV$md$,18,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu19$md$,$md$TNDN_ND320-2025$md$,$md$Điều 19. Thuế suất ưu đãi$md$,$md$Thuế suất ưu đãi
1. Áp dụng thuế suất 10% trong 15 năm đối với:
a) Thu nhập của doanh nghiệp từ thực hiện dự án đầu tư mới quy định tại các
điểm a, b, c, d và đ khoản 2 Điều 18; thu nhập của doanh nghiệp quy định tại điểm
e khoản 2 Điều 18 của Nghị định này;
b) Thu nhập của doanh nghiệp từ thực hiện dự án đầu tư quy định tại điểm g và
điểm h khoản 2 Điều 18 của Nghị định này;
c) Thu nhập của doanh nghiệp từ thực hiện dự án đầu tư mới thuộc địa bàn quy
định tại điểm a khoản 3 Điều 18 của Nghị định này;
d) Thu nhập của doanh nghiệp từ thực hiện dự án đầu tư mới tại khu công nghệ
cao, khu nông nghiệp ứng dụng công nghệ cao, khu công nghệ số tập trung; dự án
đầu tư mới tại khu kinh tế nằm trên địa bàn ưu đãi thuế quy định tại điểm a và
điểm b khoản 3 Điều 18 của Nghị định này, bao gồm cả trường hợp dự án đầu tư
mới tại khu kinh tế mà vị trí thực hiện dự án đầu tư mới có trên 50% phần diện tích
nằm trên địa bàn ưu đãi thuế quy định tại điểm a và điểm b khoản 3 Điều 18 của
Nghị định này.
2. Áp dụng thuế suất 10% trong suốt thời gian hoạt động đối với:
a) Thu nhập của doanh nghiệp tại địa bàn ưu đãi thuế quy định tại điểm b
khoản 3 Điều 18 của Nghị định này từ hoạt động thuộc ngành, nghề quy định tại
điểm k và điểm l khoản 2 Điều 18 của Nghị định này;
b) Thu nhập của doanh nghiệp từ hoạt động thuộc ngành, nghề quy định tại các
điểm i, r và s khoản 2 Điều 18 của Nghị định này;
c) Thu nhập của nhà xuất bản từ hoạt động thuộc ngành, nghề quy định tại
điểm t khoản 2 Điều 18 của Nghị định này;
d) Thu nhập của hợp tác xã, liên hiệp hợp tác xã quy định tại điểm q khoản 2
Điều 18 của Nghị định này không thuộc địa bàn quy định tại khoản 3 Điều 18 của
Nghị định này;
đ) Thu nhập của cơ quan báo chí thuộc ngành, nghề quy định tại điểm u khoản 2
Điều 18 của Nghị định này.
3. Áp dụng thuế suất 15% trong suốt thời gian hoạt động đối với thu nhập của
doanh nghiệp không thuộc địa bàn quy định tại khoản 3 Điều 18 của Nghị định này từ
hoạt động thuộc ngành, nghề quy định tại điểm l khoản 2 Điều 18 của Nghị định này.
4. Áp dụng thuế suất 17% trong thời gian 10 năm đối với:
a) Dự án đầu tư mới thuộc ngành, nghề ưu đãi quy định tại các điểm m, n và o
khoản 2 Điều 18 của Nghị định này;
b) Dự án đầu tư mới thực hiện tại địa bàn quy định tại điểm b khoản 3 Điều 18
của Nghị định này;
c) Dự án đầu tư mới tại khu kinh tế không nằm trên địa bàn quy định tại điểm a
và điểm b khoản 3 Điều 18 của Nghị định này, bao gồm cả trường hợp dự án đầu
tư mới của doanh nghiệp thực hiện tại khu kinh tế mà vị trí thực hiện dự án đầu tư
mới có trên 50% phần diện tích nằm trên địa bàn không phải là địa bàn ưu đãi thuế
quy định tại điểm a và điểm b khoản 3 Điều 18 của Nghị định này.
5. Áp dụng thuế suất 17% trong suốt thời gian hoạt động đối với thu nhập của
doanh nghiệp tại điểm p khoản 2 Điều 18 của Nghị định này.
6. Việc kéo dài thời gian và áp dụng thuế suất ưu đãi
a) Thủ tướng Chính phủ quyết định việc kéo dài thêm thời gian áp dụng thuế
suất ưu đãi tối đa không quá 15 năm đối với các trường hợp quy định tại điểm b và
điểm c khoản này;
b) Dự án đầu tư mới quy định tại các điểm a, b, d và đ khoản 2 Điều 18 của
Nghị định này, có quy mô vốn đầu tư tối thiểu 6.000 tỷ đồng, có ảnh hưởng lớn về
kinh tế - xã hội cần đặc biệt khuyến khích;
c) Dự án đầu tư quy định tại điểm g khoản 2 Điều 18 của Nghị định này đáp
ứng một trong các tiêu chí sau:
c1) Sản xuất sản phẩm hàng hóa có khả năng cạnh tranh toàn cầu, doanh thu
đạt trên 20.000 tỷ đồng/năm chậm nhất sau 05 năm kể từ khi có doanh thu từ dự án
đầu tư;
c2) Sử dụng thường xuyên trên 6.000 lao động được xác định theo quy định
của pháp luật về lao động;
c3) Dự án đầu tư thuộc lĩnh vực hạ tầng kinh tế kỹ thuật, bao gồm: Đầu tư phát
triển nhà máy nước, nhà máy điện, hệ thống cấp thoát nước, cầu, đường bộ, đường
sắt, cảng hàng không, cảng biển, cảng sông, sân bay, nhà ga, năng lượng mới, năng
lượng sạch, công nghiệp tiết kiệm năng lượng, dự án lọc hóa dầu;
d) Đối với dự án đầu tư mới quy định tại điểm h khoản 2 Điều 18 của Nghị
định này, Thủ tướng Chính phủ quyết định việc áp dụng thuế suất giảm không quá
50% mức thuế suất quy định tại khoản 1 Điều này; thời gian áp dụng thuế suất ưu
đãi không quá 1,5 lần so với thời gian áp dụng thuế suất ưu đãi quy định tại khoản 1
Điều này và được kéo dài thêm không quá 15 năm nhưng không vượt quá thời hạn
của dự án đầu tư.
7. Thời gian áp dụng thuế suất ưu đãi đối với thu nhập từ thực hiện dự án đầu
tư mới của doanh nghiệp quy định tại Điều này (bao gồm cả dự án nêu tại điểm g
khoản 2 Điều 18 của Nghị định này) được tính từ năm đầu tiên dự án đầu tư mới
của doanh nghiệp có doanh thu.
Trường hợp doanh nghiệp được cấp Giấy chứng nhận doanh nghiệp công nghệ
cao, Giấy chứng nhận doanh nghiệp nông nghiệp ứng dụng công nghệ cao, Giấy
chứng nhận doanh nghiệp khoa học và công nghệ, Giấy chứng nhận dự án ứng
dụng công nghệ cao, Giấy xác nhận ưu đãi dự án sản xuất sản phẩm công nghiệp
hỗ trợ sau thời điểm phát sinh doanh thu thì thời gian áp dụng thuế suất ưu đãi
được tính kể từ năm được cấp Giấy chứng nhận, Giấy xác nhận ưu đãi.$md$,$md$TNDN_ND320-2025_ChươngV$md$,19,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu20$md$,$md$TNDN_ND320-2025$md$,$md$Điều 20. Miễn thuế, giảm thuế$md$,$md$Miễn thuế, giảm thuế
1. Miễn thuế 04 năm và giảm 50% số thuế phải nộp trong 09 năm tiếp theo đối với:
a) Thu nhập của doanh nghiệp quy định tại khoản 1 Điều 19 của Luật này;
b) Thu nhập của doanh nghiệp quy định tại điểm r khoản 2 Điều 18 của Nghị
định này thuộc địa bàn quy định tại điểm a và điểm b khoản 3 Điều 18 của Nghị
định này; trường hợp thu nhập của doanh nghiệp quy định tại điểm r khoản 2
Điều 18 của Nghị định này không thuộc địa bàn quy định tại điểm a và điểm b
khoản 3 Điều 18 của Nghị định này được miễn thuế tối đa 04 năm và giảm 50% số
thuế phải nộp tối đa không quá 05 năm tiếp theo.
2. Miễn thuế 02 năm và giảm 50% số thuế phải nộp trong 04 năm tiếp theo đối
với thu nhập của doanh nghiệp quy định tại khoản 4 Điều 19 của Nghị định này.
3. Đối với các dự án đầu tư mới quy định tại các điểm h khoản 2 Điều 18 của
Nghị định này, Thủ tướng Chính phủ quyết định kéo dài thời gian miễn thuế, giảm
thuế tối đa không quá 1,5 lần thời gian miễn thuế, giảm thuế quy định tại khoản 1
Điều này và không vượt quá thời hạn của dự án đầu tư.
4. Thời gian miễn thuế, giảm thuế được tính từ năm đầu tiên có thu nhập chịu
thuế từ dự án đầu tư, trường hợp không có thu nhập chịu thuế trong 03 năm đầu, kể
từ năm đầu tiên có doanh thu từ dự án thì thời gian miễn thuế, giảm thuế được tính
từ năm thứ 04.
Trường hợp doanh nghiệp được cấp Giấy chứng nhận dự án ứng dụng công
nghệ cao, Giấy chứng nhận doanh nghiệp công nghệ cao, Giấy chứng nhận doanh
nghiệp nông nghiệp ứng dụng công nghệ cao, Giấy chứng nhận doanh nghiệp khoa
học và công nghệ, Giấy xác nhận ưu đãi dự án sản xuất sản phẩm công nghiệp hỗ
trợ sau thời điểm phát sinh thu nhập thì thời gian miễn thuế, giảm thuế được tính
kể từ năm được cấp Giấy chứng nhận, Giấy xác nhận ưu đãi. Trường hợp tại năm
cấp Giấy chứng nhận, Giấy xác nhận ưu đãi mà chưa có thu nhập thì thời gian
miễn thuế, giảm thuế được tính kể từ năm đầu tiên có thu nhập, nếu trong 03 năm
đầu kể từ năm được cấp Giấy chứng nhận, Giấy xác nhận ưu đãi mà doanh nghiệp
không có thu nhập chịu thuế thì thời gian miễn thuế, giảm thuế tính từ năm thứ 04
kể từ năm cấp Giấy chứng nhận, Giấy xác nhận ưu đãi.
5. Ưu đãi thuế đối với dự án đầu tư mở rộng:
a) Doanh nghiệp có dự án đầu tư đang hoạt động mở rộng quy mô, nâng cao
công suất, đổi mới công nghệ, giảm ô nhiễm hoặc cải thiện môi trường thuộc
ngành, nghề, địa bàn ưu đãi thuế thu nhập doanh nghiệp quy định tại Điều 18 Nghị
định này (sau đây gọi là đầu tư mở rộng) thì phần thu nhập tăng thêm từ đầu tư mở
rộng được hưởng ưu đãi thuế theo dự án đang hoạt động cho thời gian còn lại và
không phải hạch toán riêng khoản thu nhập tăng thêm từ đầu tư mở rộng với thu
nhập từ dự án đang hoạt động;
b) Trường hợp dự án đang hoạt động đã hết thời gian hưởng ưu đãi thuế thì
khoản thu nhập tăng thêm từ dự án đầu tư mở rộng đáp ứng các tiêu chí quy định
tại khoản 6 Điều này được miễn thuế, giảm thuế và không được hưởng ưu đãi về
thuế suất. Thời gian miễn thuế, giảm thuế đối với thu nhập tăng thêm do đầu tư mở
rộng bằng với thời gian miễn thuế, giảm thuế áp dụng đối với dự án đầu tư mới
cùng ngành, nghề, địa bàn ưu đãi thuế thu nhập doanh nghiệp và được tính từ năm
dự án đầu tư hoàn thành số vốn đầu tư đã đăng ký.
b1) Doanh nghiệp phải hạch toán riêng khoản thu nhập tăng thêm từ đầu tư mở
rộng để áp dụng ưu đãi. Trường hợp không hạch toán riêng được thì thu nhập từ
hoạt động đầu tư mở rộng xác định theo tỷ lệ giữa nguyên giá tài sản cố định đầu
tư mới đưa vào sử dụng cho sản xuất, kinh doanh trên tổng nguyên giá tài sản cố
định của doanh nghiệp;
b2) Trường hợp trong kỳ tính thuế, doanh nghiệp không tính riêng được thu
nhập tăng thêm do đầu tư mở rộng thì thu nhập tăng thêm do đầu tư mở rộng được
áp dụng ưu đãi thuế thu nhập doanh nghiệp như sau:
Phần thu nhập
tăng thêm do đầu
tư mở rộng được
áp dụng ưu đãi
thuế thu nhập
doanh nghiệp
=
Tổng thu nhập chịu
thuế trong kỳ tính
thuế (không bao
gồm thu nhập khác
không được hưởng
ưu đãi)
x
Nguyên giá tài sản cố
định đầu tư mở rộng đưa
vào sử dụng cho sản
xuất, kinh doanh
Tổng nguyên giá tài sản
cố định của doanh
nghiệp
b3) Tổng nguyên giá tài sản cố định của doanh nghiệp gồm: Nguyên giá tài sản
cố định đầu tư mở rộng đưa vào sử dụng cho sản xuất, kinh doanh và nguyên giá
tài sản cố định hiện có đang dùng cho sản xuất, kinh doanh theo số liệu cuối kỳ
trên Bảng cân đối kế toán (Báo cáo tình hình tài chính) năm;
c) Ưu đãi thuế quy định tại khoản này không áp dụng đối với các trường hợp đầu
tư mở rộng do sáp nhập, mua lại doanh nghiệp hoặc dự án đầu tư đang hoạt động.
6. Dự án đầu tư mở rộng được hưởng ưu đãi quy định tại điểm b khoản 5 Điều
này phải đáp ứng một trong các tiêu chí sau:
a) Nguyên giá tài sản cố định tăng thêm khi dự án đầu tư hoàn thành việc giải
ngân số vốn đầu tư mở rộng đã đăng ký đạt tối thiểu từ 40 tỷ đồng đối với dự án đầu
tư mở rộng thuộc ngành, nghề hưởng ưu đãi thuế thu nhập doanh nghiệp theo quy
định của Nghị định này hoặc từ 20 tỷ đồng đối với dự án đầu tư mở rộng thực hiện
tại các địa bàn quy định tại điểm a và điểm b khoản 3 Điều 18 của Nghị định này;
b) Tỷ trọng nguyên giá tài sản cố định khi dự án đầu tư hoàn thành việc giải
ngân số vốn đầu tư mở rộng đã đăng ký tăng thêm đạt tối thiểu từ 20% so với tổng
nguyên giá tài sản cố định trước khi bắt đầu đầu tư mở rộng;
c) Công suất thiết kế tăng thêm khi dự án đầu tư hoàn thành việc giải ngân số
vốn đầu tư mở rộng đã đăng ký tối thiểu từ 20% so với công suất thiết kế trước khi
bắt đầu đầu tư mở rộng.
Thời gian miễn thuế, giảm thuế quy định tại khoản này được tính từ năm dự án
đầu tư mở rộng hoàn thành số vốn đầu tư đã đăng ký và có thu nhập; trường hợp
không có thu nhập chịu thuế trong ba năm đầu, kể từ năm đầu tiên hoàn thành số
vốn đầu tư đã đăng ký từ dự án đầu tư mở rộng thì thời gian miễn thuế, giảm thuế
được tính từ năm thứ tư dự án đầu tư mở rộng hoàn thành số vốn đầu tư đã đăng
ký. Số vốn đầu tư đăng ký đã hoàn thành giải ngân được xác định bằng chênh lệch
giữa nguyên giá tổng tài sản cố định trên Bảng cân đối kế toán (Báo cáo tình hình
tài chính) của doanh nghiệp tại thời điểm doanh nghiệp hoàn thành dự án đầu tư
mở rộng so với thời điểm trước khi thực hiện đầu tư mở rộng. Trong thời gian
doanh nghiệp chưa hoàn thành giải ngân số vốn đầu tư đã đăng ký thì doanh
nghiệp không được hưởng ưu đãi thuế cho dự án đầu tư mở rộng.
Bộ trưởng Bộ Tài chính hướng dẫn việc đăng ký số vốn đầu tư để thực hiện dự
án đầu tư mở rộng của doanh nghiệp.$md$,$md$TNDN_ND320-2025_ChươngV$md$,20,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu21$md$,$md$TNDN_ND320-2025$md$,$md$Điều 21. Các trường hợp miễn thuế, giảm thuế khác$md$,$md$Các trường hợp miễn thuế, giảm thuế khác
1. Doanh nghiệp sản xuất, xây dựng, vận tải (trừ đơn vị sự nghiệp, văn phòng
thuộc các tập đoàn, tổng công ty không trực tiếp sản xuất, kinh doanh) sử dụng từ
10 đến 100 lao động nữ, trong đó số lao động nữ chiếm trên 50% tổng số lao động
có mặt thường xuyên hoặc sử dụng thường xuyên trên 100 lao động nữ mà số lao
động nữ chiếm trên 30% tổng số lao động có mặt thường xuyên của doanh nghiệp,
được giảm thuế thu nhập doanh nghiệp bằng số chi thêm cho lao động nữ gồm:
a) Chi đào tạo lại nghề;
b) Chi phí tiền lương và phụ cấp (nếu có) cho cô giáo dạy ở nhà trẻ, mẫu giáo
do doanh nghiệp tổ chức và quản lý;
c) Chi khám sức khỏe thêm trong năm;
d) Chi bồi dưỡng cho lao động nữ sau khi sinh con theo mức chi cụ thể do cơ
quan có thẩm quyền quy định;
đ) Lương, phụ cấp trả cho thời gian lao động nữ được nghỉ sau khi sinh con,
nghỉ cho con bú theo chế độ nhưng vẫn làm việc.
Số chi thêm cho lao động nữ được giảm thuế thu nhập doanh nghiệp quy định
tại khoản này phải đáp ứng điều kiện về hóa đơn, chứng từ thanh toán không dùng
tiền mặt quy định tại khoản 1 Điều 9 của Nghị định này.
2. Doanh nghiệp sử dụng lao động là người dân tộc thiểu số được giảm thuế
thu nhập doanh nghiệp bằng số chi thêm cho lao động là người dân tộc thiểu số,
bao gồm: Chi đào tạo nghề, tiền hỗ trợ về nhà ở, bảo hiểm xã hội, bảo hiểm y tế
cho người dân tộc thiểu số trong trường hợp chưa được Nhà nước hỗ trợ theo chế
độ quy định.
Số chi thêm cho lao động là người dân tộc thiểu số được giảm thuế thu nhập
doanh nghiệp quy định tại khoản này phải đáp ứng điều kiện về hóa đơn, chứng từ
thanh toán không dùng tiền mặt quy định tại khoản 1 Điều 9 của Nghị định này.
3. Doanh nghiệp thực hiện chuyển giao công nghệ thuộc lĩnh vực ưu tiên
chuyển giao cho tổ chức, cá nhân ở địa bàn có điều kiện kinh tế - xã hội khó khăn,
đơn vị sự nghiệp công lập cung cấp dịch vụ sự nghiệp công ở địa bàn có điều kiện
kinh tế - xã hội khó khăn được giảm 50% số thuế thu nhập doanh nghiệp tính trên
phần thu nhập từ chuyển giao công nghệ, thu nhập từ cung cấp dịch vụ sự nghiệp
công ở địa bàn có điều kiện kinh tế - xã hội khó khăn.
Địa bàn có điều kiện kinh tế - xã hội khó khăn theo quy định tại điểm b khoản 3
Điều 18 của Nghị định này.
4. Doanh nghiệp quy định tại khoản 2 và khoản 3 Điều 11 của Nghị định này
thành lập mới từ hộ kinh doanh (bao gồm cá nhân kinh doanh chuyển đổi lên
doanh nghiệp) được miễn thuế thu nhập doanh nghiệp trong 02 năm liên tục kể từ
khi có thu nhập chịu thuế.
a) Thời gian miễn thuế quy định tại khoản này được tính liên tục từ năm đầu
tiên doanh nghiệp có thu nhập chịu thuế, trường hợp không có thu nhập chịu thuế
trong ba năm đầu, kể từ năm đầu tiên có doanh thu thì thời gian miễn thuế được
tính từ năm thứ 04.
Trường hợp trong kỳ tính thuế đầu tiên của doanh nghiệp có thời gian sản xuất,
kinh doanh được miễn thuế dưới 12 tháng, doanh nghiệp được lựa chọn hưởng
miễn thuế ngay kỳ tính thuế đó hoặc đăng ký với cơ quan thuế thời gian bắt đầu
được miễn thuế từ kỳ tính thuế tiếp theo. Trường hợp doanh nghiệp đăng ký thời
gian miễn thuế vào kỳ tính thuế tiếp theo thì phải xác định số thuế phải nộp của kỳ
tính thuế đầu tiên để nộp ngân sách nhà nước theo quy định;
b) Sau thời gian miễn thuế quy định tại khoản này, trường hợp doanh nghiệp
thực hiện dự án đầu tư thuộc ngành, nghề, địa bàn ưu đãi thuế quy định tại Điều 18
của Nghị định này thì tiếp tục được hưởng mức ưu đãi (thuế suất ưu đãi và miễn
thuế, giảm thuế) tương ứng theo quy định tại Điều 19 và Điều 20 của Nghị định này.
Hết thời gian miễn thuế và thời gian hưởng ưu đãi thuế (nếu có) quy định tại
khoản này, doanh nghiệp thực hiện mức thuế suất thuế thu nhập doanh nghiệp theo
quy định tại khoản 2 và khoản 3 Điều 11 của Nghị định này;
c) Hộ kinh doanh, cá nhân kinh doanh quy định tại khoản này phải đáp ứng
điều kiện đã đăng ký và hoạt động theo quy định của pháp luật, đồng thời có thời
gian sản xuất, kinh doanh liên tục ít nhất là 12 tháng tính đến ngày được cấp Giấy
chứng nhận đăng ký doanh nghiệp lần đầu;
d) Doanh nghiệp thành lập mới được miễn thuế, ưu đãi thuế theo quy định tại
khoản này là doanh nghiệp đăng ký kinh doanh lần đầu, không bao gồm trường
hợp doanh nghiệp thành lập mới mà người đại diện theo pháp luật (trừ trường hợp
người đại diện theo pháp luật không phải là thành viên góp vốn), thành viên hợp
danh hoặc người có số vốn góp cao nhất đã tham gia hoạt động kinh doanh với vai
trò là người đại diện theo pháp luật, thành viên hợp danh hoặc người có số vốn góp
cao nhất trong các doanh nghiệp đang hoạt động hoặc đã giải thể nhưng chưa được
12 tháng tính từ thời điểm giải thể doanh nghiệp cũ đến thời điểm thành lập doanh
nghiệp mới.
5. Tổ chức khoa học và công nghệ công lập, cơ sở giáo dục đại học công lập
hoạt động không vì mục tiêu lợi nhuận được miễn thuế như sau:
a) Tổ chức khoa học và công nghệ công lập theo quy định của pháp luật về
khoa học, công nghệ và đổi mới sáng tạo hoạt động không vì mục tiêu lợi nhuận
được miễn thuế đối với thu nhập từ thực hiện nghiên cứu khoa học, phát triển công
nghệ và thu nhập từ cung cấp dịch vụ khoa học, công nghệ và đổi mới sáng tạo;
b) Cơ sở giáo dục đại học công lập theo quy định của Luật Giáo dục đại học
hoạt động không vì mục tiêu lợi nhuận được miễn thuế đối với khoản thu quy
định tại Điều 64 của Luật Giáo dục đại học năm 2012 (được sửa đổi, bổ sung tại
khoản 32 Điều 1 của Luật sửa đổi, bổ sung một số điều của Luật Giáo dục đại
học năm 2018).$md$,$md$TNDN_ND320-2025_ChươngV$md$,21,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu22$md$,$md$TNDN_ND320-2025$md$,$md$Điều 22. Trích lập Quỹ phát triển khoa học và công nghệ của doanh nghiệp$md$,$md$Trích lập Quỹ phát triển khoa học và công nghệ của doanh nghiệp
1. Việc trích lập Quỹ phát triển khoa học và công nghệ của doanh nghiệp được
thực hiện theo quy định tại Điều 17 Luật Thuế thu nhập doanh nghiệp.
2. Lãi suất tính lãi đối với số thuế thu hồi tính trên phần Quỹ không sử dụng
hết quy định tại khoản 2 Điều 17 của Luật Thuế thu nhập doanh nghiệp là lãi suất
trái phiếu kho bạc loại kỳ hạn 05 năm hoặc kỳ hạn 10 năm (trong trường hợp
không có loại kỳ hạn 05 năm) được phát hành gần thời điểm thu hồi nhất và thời
gian tính lãi là 02 năm, kể cả trường hợp doanh nghiệp hoàn nhập Quỹ trước thời
hạn 05 năm.
3. Hàng năm, doanh nghiệp tự quyết định mức trích lập Quỹ phát triển khoa
học và công nghệ theo quy định và lập Báo cáo trích lập, sử dụng Quỹ phát triển
khoa học và công nghệ cùng tờ khai quyết toán thuế thu nhập doanh nghiệp.
Trường hợp doanh nghiệp đã lựa chọn trích lập Quỹ phát triển khoa học, công
nghệ và đổi mới sáng tạo, chuyển đổi số theo quy định tại Nghị quyết số
198/2025/QH15 ngày 17 tháng 5 năm 2025 của Quốc hội về một số cơ chế, chính
sách đặc biệt phát triển kinh tế tư nhân thì không trích lập Quỹ phát triển khoa học
và công nghệ theo quy định tại Luật Thuế thu nhập doanh nghiệp.
4. Bộ trưởng Bộ Tài chính quy định về nghĩa vụ thuế trong trường hợp tài sản
cố định đã được hình thành từ nguồn Quỹ để phục vụ cho hoạt động nghiên cứu
khoa học và công nghệ chưa hết hao mòn mà được doanh nghiệp chuyển sang
phục vụ hoạt động sản xuất, kinh doanh của doanh nghiệp và mẫu Báo cáo trích
lập, sử dụng Quỹ phát triển khoa học và công nghệ của doanh nghiệp.$md$,$md$TNDN_ND320-2025_ChươngV$md$,22,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu23$md$,$md$TNDN_ND320-2025$md$,$md$Điều 23. Điều kiện áp dụng ưu đãi thuế thu nhập doanh nghiệp$md$,$md$Điều kiện áp dụng ưu đãi thuế thu nhập doanh nghiệp
Điều kiện áp dụng ưu đãi thuế thu nhập doanh nghiệp thực hiện theo quy định
tại Điều 18 Luật Thuế thu nhập doanh nghiệp.
1. Trong thời gian đang được hưởng ưu đãi thuế thu nhập doanh nghiệp nếu
doanh nghiệp thực hiện nhiều hoạt động sản xuất, kinh doanh thì doanh nghiệp
phải hạch toán riêng thu nhập từ hoạt động sản xuất, kinh doanh được ưu đãi thuế
quy định tại các Điều 4, 19, 20 và 21 của Nghị định này với thu nhập từ hoạt động
sản xuất, kinh doanh không được ưu đãi thuế.
a) Trường hợp trong kỳ tính thuế, doanh nghiệp không hạch toán riêng thu
nhập từ hoạt động sản xuất, kinh doanh được hưởng ưu đãi thuế và thu nhập từ
hoạt động sản xuất, kinh doanh không được hưởng ưu đãi thuế thì phần thu nhập
của hoạt động sản xuất, kinh doanh ưu đãi thuế xác định bằng tổng thu nhập chịu
thuế nhân với tỷ lệ phần trăm (%) doanh thu hoặc chi phí được trừ của hoạt động
sản xuất, kinh doanh ưu đãi thuế so với tổng doanh thu hoặc tổng chi phí được trừ
của doanh nghiệp trong kỳ tính thuế;
b) Trường hợp có khoản doanh thu hoặc chi phí được trừ không thể hạch toán
riêng được thì khoản doanh thu hoặc chi phí được trừ đó xác định theo tỷ lệ giữa
doanh thu hoặc chi phí được trừ của hoạt động sản xuất, kinh doanh hưởng ưu đãi
thuế trên tổng doanh thu hoặc chi phí được trừ của doanh nghiệp.
2. Trong cùng một thời gian, nếu doanh nghiệp được hưởng nhiều mức ưu đãi
thuế khác nhau đối với cùng một khoản thu nhập thì doanh nghiệp được lựa chọn
áp dụng mức ưu đãi thuế có lợi nhất:
a) Trường hợp doanh nghiệp đang trong thời gian hưởng ưu đãi thuế thu nhập
doanh nghiệp mà lựa chọn chuyển sang áp dụng ưu đãi thuế theo tiêu chí khác có
mức ưu đãi thuế có lợi hơn thì phải trừ đi thời gian ưu đãi (số năm đã áp dụng
miễn thuế, giảm thuế và thuế suất ưu đãi) đã hưởng;
b) Trường hợp doanh nghiệp đã hưởng hết ưu đãi thuế thu nhập doanh nghiệp
theo quy định của các văn bản quy phạm pháp luật về thuế thu nhập doanh nghiệp
mà được cấp Giấy chứng nhận doanh nghiệp công nghệ cao, Giấy chứng nhận
doanh nghiệp nông nghiệp ứng dụng công nghệ cao, Giấy chứng nhận doanh nghiệp
khoa học và công nghệ, Giấy chứng nhận dự án ứng dụng công nghệ cao, Giấy xác
nhận ưu đãi dự án sản xuất sản phẩm công nghiệp hỗ trợ thì được hưởng ưu đãi cho
thời gian còn lại. Thời gian ưu đãi còn lại được xác định bằng mức ưu đãi áp dụng
cho doanh nghiệp công nghệ cao, doanh nghiệp nông nghiệp ứng dụng công nghệ
cao, doanh nghiệp khoa học công nghệ, dự án ứng dụng công nghệ cao, dự án sản
xuất sản phẩm công nghiệp hỗ trợ trừ đi thời gian ưu đãi đã hưởng trước đó theo quy
định của pháp luật về thuế thu nhập doanh nghiệp (số năm đã áp dụng miễn thuế,
giảm thuế và thuế suất ưu đãi);
c) Trường hợp doanh nghiệp có khoản thu nhập trong lĩnh vực nông nghiệp,
lâm nghiệp, ngư nghiệp, diêm nghiệp vừa đáp ứng điều kiện theo ngành, nghề ưu
đãi thuế khác hoặc theo địa bàn ưu đãi mà doanh nghiệp lựa chọn hưởng ưu đãi
theo ngành, nghề ưu đãi khác hoặc theo địa bàn ưu đãi thuế thì sau khi hết thời
gian ưu đãi theo ngành nghề ưu đãi khác hoặc theo địa bàn ưu đãi (bao gồm cả thời
gian miễn thuế, giảm thuế và thuế suất ưu đãi) thì được chuyển sang áp dụng mức
thuế suất ưu đãi hoặc miễn thuế áp dụng đối với lĩnh vực nông nghiệp, lâm nghiệp,
ngư nghiệp, diêm nghiệp theo quy định tại Nghị định này;
d) Trường hợp doanh nghiệp đã lựa chọn hưởng ưu đãi theo quy định tại các
điểm a, b và c khoản này thì áp dụng mức ưu đãi đã lựa chọn cho toàn bộ thời gian
hưởng ưu đãi còn lại; sau khi lựa chọn doanh nghiệp không được chuyển sang áp
dụng ưu đãi theo tiêu chí khác.
3. Áp dụng ưu đãi thuế thu nhập doanh nghiệp theo tiêu chí địa bàn ưu đãi thuế
thu nhập doanh nghiệp:
a) Doanh nghiệp có dự án đầu tư sản xuất hưởng ưu đãi thuế theo tiêu chí địa
bàn ưu đãi thuế thu nhập doanh nghiệp mà có phát sinh thu nhập từ cung cấp sản
phẩm, hàng hóa do dự án sản xuất ra ngoài địa bàn thực hiện dự án đầu tư thì cũng
được hưởng ưu đãi thuế đối với khoản thu nhập này;
b) Dự án đầu tư trong lĩnh vực thương mại, dịch vụ tại địa bàn ưu đãi thuế thu
nhập doanh nghiệp (bao gồm cả khu kinh tế, khu công nghệ cao, khu nông nghiệp
ứng dụng công nghệ cao, khu công nghệ số tập trung) chỉ được hưởng ưu đãi đối với
thu nhập của dự án đầu tư phát sinh tại địa bàn thực hiện dự án đầu tư.
Doanh nghiệp có dự án đầu tư trong lĩnh vực kinh doanh vận tải được hưởng
ưu đãi thuế thu nhập doanh nghiệp do đáp ứng điều kiện ưu đãi về địa bàn thì
doanh nghiệp được hưởng ưu đãi thuế thu nhập doanh nghiệp đối với thu nhập từ
hoạt động dịch vụ vận tải căn cứ theo địa bàn thành lập dự án đầu tư thuộc địa bàn
được hưởng ưu đãi thuế và có điểm đi hoặc điểm đến thuộc địa bàn thành lập dự
án đầu tư.
4. Doanh nghiệp có dự án đầu tư được hưởng ưu đãi thuế thu nhập doanh
nghiệp theo quy định của pháp luật về thuế thu nhập doanh nghiệp tại thời điểm
cấp phép hoặc cấp Giấy chứng nhận đăng ký đầu tư hoặc được phép đầu tư theo
quy định của pháp luật về đầu tư. Trường hợp pháp luật về thuế thu nhập doanh
nghiệp có thay đổi mà doanh nghiệp đáp ứng điều kiện ưu đãi thuế theo quy định
của pháp luật mới được sửa đổi, bổ sung thì doanh nghiệp được lựa chọn hưởng ưu
đãi về thuế suất và về thời gian miễn thuế, giảm thuế theo quy định của pháp luật
tại thời điểm cấp phép, cấp Giấy chứng nhận đăng ký đầu tư, được phép đầu tư
hoặc theo quy định của pháp luật mới được sửa đổi, bổ sung cho thời gian còn lại
kể từ kỳ tính thuế năm 2025.
Trường hợp doanh nghiệp có dự án đầu tư mà không thuộc diện được hưởng
ưu đãi theo quy định của các văn bản quy phạm pháp luật về thuế thu nhập doanh
nghiệp trước thời điểm Nghị định này có hiệu lực nhưng thuộc diện hưởng ưu đãi
theo quy định của Nghị định này thì được áp dụng ưu đãi theo quy định của Nghị định
này cho thời gian còn lại kể từ kỳ tính thuế năm 2025.
5. Thu nhập được miễn thuế, ưu đãi thuế trong lĩnh vực nông nghiệp, lâm
nghiệp, ngư nghiệp, diêm nghiệp tại Nghị định này bao gồm cả thu nhập từ thanh
lý tài sản là sản phẩm nông nghiệp, lâm nghiệp, ngư nghiệp, diêm nghiệp và thu
nhập từ việc bán phế liệu, phế phẩm là sản phẩm nông nghiệp, lâm nghiệp, ngư
nghiệp, diêm nghiệp.
6. Trường hợp dự án đầu tư mới của doanh nghiệp tại năm đầu tiên phát sinh
doanh thu, thu nhập được hưởng ưu đãi thuế có thời gian dưới 12 tháng, doanh
nghiệp được lựa chọn hưởng ưu đãi thuế (thuế suất, thời gian miễn thuế, giảm
thuế) đối với dự án đầu tư ngay từ kỳ tính thuế phát sinh doanh thu, thu nhập đó
hoặc đăng ký với cơ quan thuế thời gian bắt đầu được hưởng ưu đãi thuế từ kỳ tính
thuế tiếp theo. Trường hợp doanh nghiệp đăng ký thời gian áp dụng ưu đãi thuế
của dự án đầu tư mới vào kỳ tính thuế tiếp theo thì phải xác định số thuế phải nộp
từ dự án đầu tư này của năm đầu tiên phát sinh doanh thu, thu nhập để nộp vào
ngân sách nhà nước theo quy định.
a) Trường hợp doanh nghiệp công nghệ cao, doanh nghiệp nông nghiệp ứng
dụng công nghệ cao, doanh nghiệp khoa học và công nghệ trong kỳ tính thuế đầu
tiên phát sinh doanh thu hoặc trong kỳ tính thuế đầu tiên có thu nhập có thời gian
phát sinh doanh thu, thu nhập được hưởng ưu đãi thuế dưới 12 tháng, doanh nghiệp
được lựa chọn hưởng ưu đãi thuế (thuế suất, thời gian miễn thuế, giảm thuế) ngay
từ kỳ tính thuế đầu tiên đó hoặc đăng ký với cơ quan thuế thời gian bắt đầu được
hưởng ưu đãi thuế từ kỳ tính thuế tiếp theo. Trường hợp doanh nghiệp đăng ký thời
gian ưu đãi thuế vào kỳ tính thuế tiếp theo thì phải xác định số thuế phải nộp của
kỳ tính thuế đầu tiên để nộp vào ngân sách nhà nước theo quy định.
b) Trường hợp doanh nghiệp thực hiện chuyển đổi kỳ tính thuế thu nhập doanh
nghiệp (bao gồm cả chuyển đổi kỳ tính thuế từ năm dương lịch sang năm tài chính
hoặc ngược lại) thì kỳ tính thuế thu nhập doanh nghiệp của năm chuyển đổi không
vượt quá 12 tháng. Doanh nghiệp đang trong thời gian được hưởng ưu đãi thuế thu
nhập doanh nghiệp mà có thực hiện chuyển đổi kỳ tính thuế thì doanh nghiệp được
lựa chọn: Ưu đãi trong năm chuyển đổi kỳ tính thuế hoặc nộp thuế theo mức thuế
suất không được hưởng ưu đãi của năm chuyển đổi kỳ tính thuế và hưởng ưu đãi
thuế sang năm tiếp theo.
7. Doanh nghiệp thành lập hoặc doanh nghiệp có dự án đầu tư từ việc sáp
nhập, hợp nhất, chia, tách, chuyển đổi chủ sở hữu, chuyển đổi loại hình doanh
nghiệp có trách nhiệm thực hiện nghĩa vụ nộp thuế thu nhập doanh nghiệp (kể cả
tiền phạt nếu có), đồng thời được kế thừa các ưu đãi thuế thu nhập doanh nghiệp
(kể cả các khoản lỗ chưa được kết chuyển) của doanh nghiệp hoặc dự án đầu tư
trước khi chuyển đổi, chia, tách, sáp nhập, hợp nhất nếu tiếp tục đáp ứng các điều
kiện ưu đãi thuế thu nhập doanh nghiệp, điều kiện chuyển lỗ theo quy định.
8. Ưu đãi thuế thu nhập doanh nghiệp theo diện dự án đầu tư mới:
a) Dự án đầu tư mới được hưởng ưu đãi thuế thu nhập doanh nghiệp quy định
tại Điều 19 và Điều 20 của Nghị định này phải được cơ quan Nhà nước có thẩm
quyền cấp Giấy chứng nhận đăng ký đầu tư hoặc được chấp thuận chủ trương đầu
tư theo quy định của pháp luật về đầu tư hoặc cho phép đầu tư theo quy định của
pháp luật chuyên ngành.
Đối với các dự án đầu tư không thuộc diện phải cấp Giấy chứng nhận đăng
ký đầu tư, chấp thuận chủ trương đầu tư theo quy định của pháp luật về đầu tư
hoặc cho phép đầu tư theo quy định của pháp luật chuyên ngành thì việc xác định
dự án đầu tư mới căn cứ vào Báo cáo thực hiện dự án đầu tư của doanh nghiệp
theo quy định của pháp luật về đầu tư gửi cơ quan đăng ký đầu tư;
b) Dự án đầu tư mới được hưởng ưu đãi thuế thu nhập doanh nghiệp theo diện
đầu tư mới không bao gồm các các trường hợp sau:
b1) Dự án đầu tư hình thành từ việc: Sáp nhập, hợp nhất, chia, tách, chuyển
đổi loại hình doanh nghiệp theo quy định của pháp luật.
b2) Dự án đầu tư hình thành từ việc chuyển đổi chủ sở hữu (bao gồm cả trường
hợp thực hiện dự án đầu tư mới nhưng vẫn kế thừa tài sản, địa điểm kinh doanh,
ngành nghề kinh doanh của doanh nghiệp cũ để tiếp tục hoạt động sản xuất, kinh
doanh; mua lại dự án đầu tư đang hoạt động);
c) Đối với doanh nghiệp đang được hưởng ưu đãi thuế thu nhập doanh nghiệp
theo diện doanh nghiệp mới thành lập từ dự án đầu tư thì ưu đãi thuế chỉ áp dụng
đối với thu nhập từ hoạt động sản xuất, kinh doanh đáp ứng điều kiện ưu đãi đầu tư
ghi trong Giấy chứng nhận đăng ký doanh nghiệp hoặc Giấy chứng nhận đầu tư lần
đầu của doanh nghiệp. Đối với doanh nghiệp đang hoạt động sản xuất, kinh doanh
nếu có sự thay đổi Giấy chứng nhận đăng ký doanh nghiệp hoặc Giấy chứng nhận
đầu tư nhưng sự thay đổi đó không làm thay đổi việc đáp ứng các điều kiện ưu đãi
thuế của dự án đó theo quy định thì doanh nghiệp tiếp tục được hưởng ưu đãi thuế
cho thời gian còn lại hoặc ưu đãi theo diện đầu tư mở rộng nếu đáp ứng điều kiện
ưu đãi theo quy định;
d) Đối với dự án đầu tư được cấp Giấy chứng nhận đăng ký đầu tư hoặc được
phép đầu tư theo quy định của pháp luật về đầu tư mà trong Hồ sơ đăng ký đầu tư
lần đầu gửi cơ quan cấp phép đầu tư đã đăng ký số vốn đầu tư, phân kỳ đầu tư kèm
tiến độ thực hiện đầu tư, trường hợp các giai đoạn tiếp theo thực tế có thực hiện
được coi là dự án thành phần của dự án đầu tư đã được cấp phép lần đầu nếu thực
hiện theo tiến độ (trừ trường hợp bất khả kháng, khó khăn do nguyên nhân khách
quan trong khâu giải phóng mặt bằng, giải quyết thủ tục hành chính của cơ quan
Nhà nước, do thiên tai, hỏa hoạn hoặc khó khăn, bất khả kháng khác) thì các dự án
thành phần của dự án đầu tư lần đầu được hưởng ưu đãi thuế cho thời gian còn lại
của dự án đầu tư lần đầu tính từ thời điểm dự án thành phần có thu nhập được
hưởng ưu đãi.
Trong thời gian triển khai các dự án thành phần theo từng giai đoạn nêu trên nếu
nhà đầu tư được cơ quan quản lý Nhà nước về đầu tư cho phép gia hạn thực hiện dự
án theo quy định của pháp luật về đầu tư và doanh nghiệp thực hiện theo đúng thời
hạn đã được gia hạn thì cũng được hưởng ưu đãi thuế theo quy định nêu trên.
9. Thuế suất 15% và 17% quy định tại khoản 2 và khoản 3 Điều 11 và quy
định về ưu đãi thuế tại các Điều 4, 19, 20 và 21 của Nghị định này không áp dụng
đối với:
a) Thu nhập từ chuyển nhượng vốn, chuyển nhượng quyền góp vốn; thu nhập
từ chuyển nhượng bất động sản, trừ thu nhập từ đầu tư xây dựng nhà ở xã hội quy
định tại điểm s khoản 2 Điều 18 của Nghị định này; thu nhập từ chuyển nhượng dự
án đầu tư (trừ chuyển nhượng dự án chế biến khoáng sản), chuyển nhượng quyền
tham gia dự án đầu tư, chuyển nhượng quyền thăm dò, khai thác, chế biến khoáng
sản; thu nhập từ hoạt động sản xuất, kinh doanh ở ngoài Việt Nam;
b) Thu nhập từ hoạt động tìm kiếm, thăm dò và khai thác dầu khí, tài nguyên
quý hiếm khác và thu nhập từ hoạt động thăm dò, khai thác khoáng sản;
c) Thu nhập từ sản xuất, kinh doanh trò chơi điện tử trên mạng; thu nhập từ
sản xuất, kinh doanh hàng hóa, dịch vụ thuộc đối tượng chịu thuế tiêu thụ đặc biệt
theo quy định của Luật Thuế tiêu thụ đặc biệt, trừ dự án sản xuất, lắp ráp ô tô, máy
bay, trực thăng, tàu lượn, du thuyền, lọc hóa dầu;
d) Các khoản thu nhập khác quy định tại khoản 3 Điều 3 của Nghị định này
không liên quan đến hoạt động sản xuất, kinh doanh được ưu đãi thuế.
Quy định tại điểm này áp dụng đối với cả trường hợp thực hiện dự án đầu tư
đáp ứng điều kiện ưu đãi về ngành, nghề quy định tại khoản 2 và điều kiện ưu đãi
về địa bàn ưu đãi đầu tư quy định tại khoản 3 Điều 18 của Nghị định này;
e) Trường hợp khác theo hướng dẫn của Bộ trưởng Bộ Tài chính.
10. Trong thời gian được ưu đãi thuế thu nhập doanh nghiệp, nếu trong kỳ tính
thuế mà doanh nghiệp không đáp ứng một trong các điều kiện ưu đãi thuế quy định
tại các khoản 1, 3, 4, 5, 6, 8, 12 và 14 Điều 4, khoản 2 và khoản 3 Điều 11, Điều 18,
Điều 19, Điều 20, Điều 21 và quy định tại Điều này thì kỳ tính thuế đó không được
hưởng ưu đãi thuế mà phải nộp thuế theo mức thuế suất 20% (đối với các trường
hợp đang hưởng ưu đãi theo các điều kiện ngành, nghề, địa bàn ưu đãi quy định tại
các Điều 18, 19 và 20 của Nghị định này thì năm đó cũng tính vào thời gian ưu đãi
mà doanh nghiệp đang đăng ký hưởng).
Đối với dự án đầu tư quy định tại điểm g và điểm h khoản 1 Điều 18, điểm c và
điểm d khoản 6 Điều 19 của Nghị định này, trường hợp sau 03 năm (đối với dự án
đầu tư quy định tại điểm g là 05 năm) kể từ khi được cấp phép đầu tư (không kể bị
chậm tiến độ do nguyên nhân khách quan trong khâu giải phóng mặt bằng, giải
quyết thủ tục hành chính của cơ quan nhà nước hoặc do thiên tai, địch họa, hỏa hoạn
hoặc khó khăn, bất khả kháng khác và được cơ quan cấp Giấy chứng nhận đầu tư
chấp thuận, báo cáo Thủ tướng Chính phủ phê duyệt) hoặc năm thứ 04 kể từ năm có
doanh thu (đối với dự án đầu tư quy định tại điểm g là năm thứ 06) mà dự án đầu tư
của doanh nghiệp không đáp ứng các điều kiện nêu tại điểm g và điểm h khoản 1
Điều 18, điểm c và điểm d khoản 6 Điều 19 của Nghị định này thì không được
hưởng ưu đãi thuế thu nhập doanh nghiệp, đồng thời doanh nghiệp phải kê khai, nộp
số tiền thuế thu nhập doanh nghiệp đã kê khai hưởng ưu đãi của các năm trước (nếu
có) theo quy định của pháp luật và không bị coi là hành vi khai sai theo quy định của
pháp luật về quản lý thuế. Trong thời gian hưởng ưu đãi thuế thu nhập doanh
nghiệp, nếu có năm tính thuế mà doanh nghiệp không đáp ứng đủ một trong các
điều kiện ưu đãi thuế quy định tại điểm g và điểm h khoản 1 Điều 18 của Nghị định
này thì năm đó doanh nghiệp không được hưởng ưu đãi thuế thu nhập doanh nghiệp.
11. Doanh nghiệp công nghệ cao, doanh nghiệp nông nghiệp ứng dụng công
nghệ cao, doanh nghiệp khoa học và công nghệ được hưởng ưu đãi thuế thu nhập
doanh nghiệp đối với thu nhập từ hoạt động công nghệ cao, ứng dụng công nghệ
cao, kết quả nghiên cứu khoa học và phát triển công nghệ và các khoản thu nhập
có liên quan trực tiếp từ hoạt động công nghệ cao, ứng dụng công nghệ cao, kết
quả nghiên cứu khoa học và phát triển công nghệ.
ĐIỀU KHOẢN THI HÀNH$md$,$md$TNDN_ND320-2025_ChươngV$md$,23,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu24$md$,$md$TNDN_ND320-2025$md$,$md$Điều 24. Hiệu lực thi hành$md$,$md$Hiệu lực thi hành
1. Nghị định này có hiệu lực thi hành kể từ ngày ký ban hành và áp dụng từ kỳ
tính thuế thu nhập doanh nghiệp năm 2025. Việc xác định thời gian áp dụng trong
một số trường hợp cụ thể như sau:
a) Doanh nghiệp được lựa chọn áp dụng quy định về doanh thu, chi phí, ưu đãi
thuế, miễn thuế, giảm thuế, chuyển lỗ tại Nghị định này từ đầu kỳ tính thuế năm
2025 hoặc từ ngày Luật Thuế thu nhập doanh nghiệp có hiệu lực hoặc từ ngày
Nghị định này có hiệu lực thi hành; trường hợp kỳ tính thuế năm 2025 của doanh
nghiệp bắt đầu sau ngày Luật Thuế thu nhập doanh nghiệp có hiệu lực thì áp dụng
từ ngày Luật Thuế thu nhập doanh nghiệp có hiệu lực hoặc từ ngày Nghị định này
có hiệu lực thi hành;
b) Quy định về chứng từ thanh toán không dùng tiền mặt tại điểm c khoản 1
Điều 9 và quy định về chuyển nhượng vốn tại điểm i khoản 3 Điều 12 của Nghị
định này áp dụng từ ngày Nghị định này có hiệu lực thi hành.
2. Nghị định này thay thế:
a) Nghị định số 218/2013/NĐ-CP ngày 26 tháng 12 năm 2013 của Chính
phủ quy định chi tiết và hướng dẫn thi hành một số điều Luật Thuế thu nhập
doanh nghiệp;
b) Nghị định số 91/2014/NĐ-CP ngày 01 tháng 10 năm 2014 của Chính phủ
sửa đổi, bổ sung một số điều tại các Nghị định về thuế;
c) Nghị định số 12/2015/NĐ-CP ngày 12 tháng 02 năm 2015 của Chính phủ
quy định chi tiết thi hành Luật sửa đổi, bổ sung một số điều của các Luật về thuế
và sửa đổi, bổ sung một số điều của các Nghị định về thuế;
d) Nghị định số 57/2021/NĐ-CP ngày 04 tháng 6 năm 2021 của Chính phủ bổ
sung điểm g khoản 2 Điều 20 Nghị định số 218/2013/NĐ-CP về ưu đãi thuế thu
nhập doanh nghiệp đối với dự án sản xuất sản phẩm công nghiệp hỗ trợ.
3. Trường hợp các văn bản quy phạm pháp luật quy định viện dẫn tại Nghị
định này được sửa đổi, bổ sung hoặc thay thế thì thực hiện theo văn bản được sửa
đổi, bổ sung hoặc thay thế đó.$md$,$md$TNDN_ND320-2025_ChươngVI$md$,24,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu25$md$,$md$TNDN_ND320-2025$md$,$md$Điều 25. Điều khoản chuyển tiếp$md$,$md$Điều khoản chuyển tiếp
1. Doanh nghiệp có dự án đầu tư mới trước ngày Luật Thuế thu nhập doanh
nghiệp có hiệu lực còn đang trong thời gian hưởng ưu đãi thuế thu nhập doanh
nghiệp, kể cả trường hợp dự án đầu tư mới chưa được hưởng ưu đãi theo quy định
của các văn bản quy phạm pháp luật về thuế thu nhập doanh nghiệp trước thời
điểm Nghị định này có hiệu lực thi hành, thì được hưởng ưu đãi cho thời gian còn
lại theo quy định của các văn bản quy phạm pháp luật tại thời điểm cấp Giấy
chứng nhận đăng ký đầu tư hoặc được chấp thuận chủ trương đầu tư theo quy định
của pháp luật về đầu tư hoặc được phép đầu tư theo quy định của pháp luật chuyên
ngành; trường hợp mức ưu đãi tại Nghị định này cao hơn mức ưu đãi đang hưởng
thì được chuyển sang áp dụng ưu đãi theo Nghị định này cho thời gian còn lại.
Thời gian còn lại quy định tại điểm này được tính từ kỳ tính thuế 2025.
2. Doanh nghiệp có dự án đầu tư mở rộng được cấp hoặc điều chỉnh Giấy
chứng nhận đăng ký đầu tư hoặc chấp thuận chủ trương đầu tư hoặc Báo cáo thực
hiện dự án đầu tư của doanh nghiệp theo quy định của pháp luật về đầu tư gửi cơ
quan đăng ký đầu tư hoặc cho phép đầu tư theo quy định của pháp luật chuyên
ngành (sau đây gọi là được phép đầu tư) trước ngày Luật Thuế thu nhập doanh
nghiệp có hiệu lực còn đang trong thời gian hưởng ưu đãi thuế thu nhập doanh
nghiệp, kể cả trường hợp dự án đầu tư mở rộng đã được cấp hoặc điều chỉnh Giấy
chứng nhận đăng ký đầu tư hoặc được phép đầu tư nhưng chưa được hưởng ưu đãi
theo quy định của các văn bản quy phạm pháp luật về thuế thu nhập doanh nghiệp
trước thời điểm Nghị định này có hiệu lực thi hành, thì được hưởng ưu đãi cho thời
gian còn lại theo quy định của các văn bản quy phạm pháp luật tại thời điểm được
cấp hoặc điều chỉnh Giấy chứng nhận đăng ký đầu tư hoặc được phép đầu tư;
trường hợp mức ưu đãi tại Nghị định này cao hơn mức ưu đãi đang hưởng (kể cả
trường hợp thuộc diện nhưng chưa được hưởng) thì được chuyển sang áp dụng ưu
đãi theo Nghị định này cho thời gian còn lại. Thời gian còn lại quy định tại điểm
này được tính từ kỳ tính thuế 2025.
Trường hợp doanh nghiệp có dự án đầu tư mở rộng được cấp hoặc điều chỉnh
Giấy chứng nhận đăng ký đầu tư hoặc chấp thuận chủ trương đầu tư hoặc được phép
đầu tư trước ngày Luật Thuế thu nhập doanh nghiệp có hiệu lực thì việc xác định ưu
đãi và thời điểm tính hưởng ưu đãi thuế đối với đầu tư mở rộng thực hiện theo quy
định của văn bản có hiệu lực tại thời điểm được cấp hoặc điều chỉnh Giấy chứng
nhận đăng ký đầu tư hoặc chấp thuận chủ trương đầu tư hoặc được phép đầu tư.
3. Doanh nghiệp có khoản thu nhập từ hoạt động được hưởng ưu đãi theo quy
định của văn bản pháp luật về thuế thu nhập doanh nghiệp trước ngày Luật Thuế
thu nhập doanh nghiệp có hiệu lực (không bao gồm dự án đầu tư quy định tại
khoản 1 và khoản 2 Điều này) mà khoản thu nhập đó không thuộc diện được ưu
đãi thuế theo quy định của Luật Thuế thu nhập doanh nghiệp thì không được
hưởng ưu đãi thuế kể từ ngày Luật Thuế thu nhập doanh nghiệp có hiệu lực.
4. Doanh nghiệp có số lỗ phát sinh trước thời điểm Nghị định này có hiệu lực
thi hành (bao gồm cả số lỗ từ hoạt động chuyển nhượng bất động sản, chuyển
nhượng dự án đầu tư, chuyển nhượng quyền tham gia dự án đầu tư) nhưng còn
trong thời hạn chuyển lỗ theo quy định thì tiếp tục được chuyển lỗ theo quy định
tại Nghị định này cho thời gian còn lại. Số lỗ từ hoạt động chuyển nhượng bất
động sản, chuyển nhượng dự án đầu tư, chuyển nhượng quyền tham gia dự án đầu
tư của các kỳ trước không được chuyển vào lãi từ hoạt động sản xuất, kinh doanh
được hưởng ưu đãi thuế.$md$,$md$TNDN_ND320-2025_ChươngVI$md$,25,$md$2025-10-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNDN_ND320-2025_Dieu26$md$,$md$TNDN_ND320-2025$md$,$md$Điều 26. Trách nhiệm thi hành$md$,$md$Trách nhiệm thi hành
1. Bộ trưởng Bộ Tài chính quy định chi tiết các Điều, khoản được giao tại
Nghị định và hướng dẫn thực hiện Nghị định này theo chức năng, nhiệm vụ, đảm
bảo yêu cầu quản lý.
2. Bộ trưởng Bộ Khoa học và Công nghệ: Xây dựng văn bản quy phạm pháp
luật trình cấp có thẩm quyền hoặc ban hành theo thẩm quyền để làm căn cứ thực
hiện các chính sách về miễn thuế, ưu đãi thuế quy định tại khoản 4 Điều 4 của
Nghị định này và các nội dung có liên quan theo chức năng, nhiệm vụ.
3. Bộ trưởng Bộ Công Thương: Xây dựng văn bản quy phạm pháp luật trình
cấp có thẩm quyền hoặc ban hành theo thẩm quyền văn bản hướng dẫn về sản
phẩm công nghiệp hỗ trợ quy định tại điểm c khoản 2 Điều 18 của Nghị định này.
4. Các Bộ trưởng, Thủ trưởng cơ quan ngang bộ, Thủ trưởng cơ quan thuộc
Chính phủ, Chủ tịch Ủy ban nhân dân tỉnh, thành phố trực thuộc Trung ương và
các tổ chức, cá nhân có liên quan chịu trách nhiệm thi hành Nghị định này./.
TM. CHÍNH PHỦ
KT. THỦ TƯỚNG
