insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K8$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 8$md$,$md$Kỳ tỉnh thuế, kỳ tính khoản thu khác (sau đây gọi là kỳ tính thuế) là
khoảng thời gian để xác định số tiền thuế, khoản thu khác phải nộp ngân sách nhà
nước theo quy định của pháp luật về thuế, pháp luật về quản lý thuế và các quy
định khác của pháp luật có liên quan bao gồm kỳ theo từng lần phát sinh, tháng,
quý, năm hoặc kỳ quyết toán.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K9$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 9$md$,$md$Hồ sơ thuế, hồ sơ khoản thu khác (sau đây gọi là hồ sơ thuế) là hồ sơ
đăng ký thuế, hồ sơ khai thuế, hồ sơ khai khoản thu khác, hồ sơ nộp thuế, hồ sơ
nộp khoản thu khác, hồ sơ gia hạn nộp hồ sơ khai thuế, hồ sơ gia hạn nộp hồ sơ
khai khoản thu khác, hồ sơ hoàn thuế, hồ sơ hoàn khoản thu khác, hồ sơ miễn
thuế, hồ sơ miễn khoản thu khác, hồ sơ giảm thuế, hồ sơ giảm khoản thu khác, hồ
sơ không chịu thuế, hồ sơ không thu thuế, hồ sơ khoanh tiền thuế nợ, hồ sơ xóa
tiền thuế nợ, hồ sơ miễn tiền chậm nộp, hồ sơ miễn tiền phạt, hồ sơ không tính
tiền chậm nộp, hồ sơ gia hạn nộp thuế, hồ sơ gia hạn nộp khoản thu khác, hồ sơ
gia hạn nộp tiền thuế nợ, hồ sơsơ nộp dần tiền thuế nợ, hồ sơ hải quan.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K10$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 10$md$,$md$Cưỡng chế thi hành quyết định hành chính về quản lý thuế là việc áp
dụng các biện pháp theo quy định của Luật này và quy định khác của pháp luật có
liên quan buộc người nộp thuế phải thực hiện nghĩa vụ thuế.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K11$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 11$md$,$md$Rủi roro về thuế là nguy cơ người nộp thuế không tuân thủ pháp luật dẫn
đến thất thu ngân sách nhà nước.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K12$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 12$md$,$md$Quản lý rủi ro trong quản lý thuế là việc cơ quan quản lý thuế áp dụng
hệ thống các biện pháp, quy trình nghiệp vụ và công cụ phân tích dữ liệu để xác
định, đánh giá, phân loại mức độ rủi ro về thuế theo tiêu chí do cơ quan quản lý
thuế quy định, nhằm phân bổ nguồn lực, áp dụng các biện pháp quản lý phù hợp,
tập trung xử lý các trường hợp rủi ro cao và kiểm soát kịp thời nguy cơ vi phạm
pháp luật trong quản lý thuế.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K13$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 13$md$,$md$Quản lý tuân thủ trong quản lý thuế là việc cơ quan quản lý thuế sử
dụng hồ sơ, thông tin, tài liệu, dữ liệu về người nộp thuế để theo dõi, đánh giá
mức độ chấp hành pháp luật về thuế và áp dụng biện pháp quản lý phù hợp nhằm
khuyến khích, hỗ trợ tuân thủ tự nguyện, áp dụng chế độ ưu tiên đối với trường
hợp tuân thủ tổt, tăng cường giám sát và xử lý kịp thời đổi với trường hợp không
tuân thủ.
