## Page 4
4$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K14$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 14$md$,$md$Hoàn thành nghĩa vụ nộp thuế là việc nộp đủ tiền thuế, khoản thu khác,
tiền chậm nộp, tiền phạt vi phạm hành chính về quản lý thuế.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K15$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 15$md$,$md$Cơ sở dữ liệu thương mại là tập hợp thông tin, số liệu kinh tế, tài chính
và thương mại do các tổ chức kinh doanh dữ liệu thu thập, xử lý, chuẩn hóa và
cung cấp trên thị trường.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K16$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 16$md$,$md$Thông tin người nộp thuế là thông tỉn, dữ liệu về người nộp thuế và
thông tin liên quan đến nghĩa vụ thuế của người nộp thuế do người nộp thuế cung
cấp, do cơ quan nhà nước, tổ chức, cá nhân liên quan có trách nhiệm cung cấp, do
cơ quan quản lý thuế thu thập được trong quá trình quản lý thuế.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K17$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 17$md$,$md$Các bên có quan hệ liên kết là các bên tham gia trực tiếp hoặc gián tiếp
vào việc điều hành, kiểm soát, góp vốn vào doanh nghiệp; các bên cùng chịu sự
điều hành, kiểm soát trực tiếp hoặc gián tiếp bởi một tổ chức hoặc cá nhân; các
bên cùng có một tổ chức hoặc cá nhân tham gia góp vốn; các doanh nghiệp được
điều hành, kiểm soát bởi các cá nhân là thành viên trong cùng một gia đình.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K18$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 18$md$,$md$Giao địch liên kết là giao dịch phát sinh giữa các bên có quan hệ liên kết.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K19$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 19$md$,$md$Giao dịch độc lập là giao dịch phát sinh giữa các bên không có quan hệ
liên kết.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K20$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 20$md$,$md$Nguyên tắc giao dịch độc lập là nguyên tắc được áp dụng trong kê khai,
xác định giá giao dịch liên kết của người nộp thuế có phát sinh giao dịch liên kết,
theo đó các điều kiện trong giao dịch liên kết được xác định tương đương với các
điều kiện trong giao dịch độc lập tương đồng trên thị trường.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều4_K21$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 21$md$,$md$Trường hợp bắt khả kháng là trường hợp người nộp thuế bị thiệt hại vật
chất do gặp thiên tai, thảm họa, dịch bệnh, hỏa hoạn, tai nạn bất ngờ và các trường
hợp bắt khả kháng khác theo quy định của Chính phủ.$md$,$md$Luật quản lý thuế 2025_Điều4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều5$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 5. Nội dung quản lý thuế$md$,$md$Nội dung quản lý thuế$md$,null,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều5_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Cơ quan thuế thực hiện quản lý thuế theo phân nhóm người nộp thuế.$md$,$md$Luật quản lý thuế 2025_Điều5$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều5_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Các nội dung quản lý thuế bao gồm:
nộp, tiền phạt; ấn định thuế; hoàn thuế; xử lý tiền thuế, tiền chậm nộp, tiền phạt
nộp thừa; miễn thuế; giảm thuế; không chịu thuế; không thu thuế; khoanh tiền
thuế nợ; xóa tiền thuế nợ; miễn tiền chậm nộp; miễn tiền phạt; tính tiền chậm nộp,
không tính tiền chậm nộp; gia hạn nộp thuế, tiền chậm nộp, tiền phạt; gia hạn nộp
hồ sơ khai thuế; nộp dần tiền thuế nợ; cưỡng chế thi hành quyết định hành chính
về quản lý thuế;
<!-- Page Break -->
## Page 5
pháp luật về thuế; xử lý vi phạm hành chính về quản lý thuế; giải quyết khiếu nại,
tố cáo về thuế;
thỏa thuận quốc tế về thuế mà nước Cộng hòa xã hội chủ nghĩa Việt Nam là thành
viên hoặc là bên ký kết, cam kết quốc tế về thuế.$md$,$md$Luật quản lý thuế 2025_Điều5$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
