insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều5_K3$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 3$md$,$md$Cơ quan thuế áp dụng các nội dung quản lý thuế quy định tại khoản 2
Điều này để quản lý khoản thu khác theo quy định của Luật này và các quy định
