lý thuế, cơ quan quản lý thuế để chuyển giá, trên thuế, khoản thu khác, gian lận,
trục lợi tiền thuế, tiền ngân sách nhà nước. Lợi dụng chức vụ, quyền hạn để tiết
lộ hoặc làm rò rỉ thông tin người nộp thuế trái quy định. Làm sai lệch kết quả kiểm
tra, xử lý vi phạm pháp luật về thuế. Gây phiền hà, sách nhiễu đối với người nộp
thuế. Lợi dụng để chiếm đoạt hoặc sử dụng trái phép tiền thuế, khoản thu khác.$md$,$md$Luật quản lý thuế 2025_Điều8$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
