kịp thời, chính xác về số tiền thuế, khoản thu khác phải nộp, số tiền thuế, khoản
thu khác được miễn, giảm, hoàn, không thu. Cản trở công chức quản lý thuế thi
hành công vụ. Chống đối, trì hoãn, không cung cấp thông tin, tài liệu phục vụ
kiểm tra, giám sát thuế, khoản thu khác.$md$,$md$Luật quản lý thuế 2025_Điều8$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
