khác; cơ quan quản lý thuế tiếp nhận, xử lý hồ sơ khai thuế, khoản thu khác.$md$,$md$Luật quản lý thuế 2025_Điều12$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 13. Khai thuế, khoản thu khác; tính thuế, khoản thu khác; khấu$md$,$md$Khai thuế, khoản thu khác; tính thuế, khoản thu khác; khấu
trừ thuế đối với hộ kinh doanh, cá nhân kinh doanh$md$,null,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Đối với thuế giá trị gia tăng, thuế thu nhập cá nhân:
thu hằng năm từ hoạt động sản xuất, kinh doanh hàng hóa, dịch vụ thuộc đối tượng
không chịu thuế, đối tượng không phải nộp thuế theo quy định của pháp luật về
thuế giá trị gia tăng, thuế thu nhập cá nhân, hộ kinh doanh, cá nhân kinh doanh
thông báo doanh thu thực tế phát sinh trong năm với cơ quan thuế;
thu hằng năm từ hoạt động sản xuất, kinh doanh hàng hóa, dịch vụ thuộc đối
tượng chịu thuế, đối tượng phải nộp thuế theo quy định của pháp luật về thuế, hộ
kinh doanh, cá nhân kinh doanh tự xác định số thuế giá trị gia tăng, thuế thu nhập
cá nhân phải nộp theo quy định của pháp luật về thuế giá trị gia tăng, thuế thu
nhập cá nhân.
Trường hợp hộ kinh doanh, cá nhân kinh doanh sử dụng hóa đơn điện tử,
hoá đơn điện tử khởi tạo từ máy tính tiền có kết nối đữ liệu với cơ quan thuế, Hệ
thống thông tin quản lý thuế tự động tạo lập tờ khai thuế để hỗ trợ hộ kinh doanh,
cá nhân kinh doanh trong việc khai thuế và tính thuế trên cơ sở dữ liệu hóa đơn
điện tử, cơ sở dữ liệu quản lý thuế và các nguồn cơ sở dữ liệu khác mà cơ quan
thuế có được từ cơ quan nhà nước khác, tổ chức, cá nhân cung cấp.$md$,$md$Luật quản lý thuế 2025_Điều13$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K1_Da$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm a$md$,$md$Trường hợp hộ kinh doanh, cá nhân kinh doanh tự xác định có mức doanh$md$,$md$Luật quản lý thuế 2025_Điều13_K1$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
