insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Đối với các loại thuế khác và khoản thu khác:
Hộ kinh doanh, cá nhân kinh doanh tự xác định số thuế, khoản thu khác phải
nộp theo quy định của pháp luật về thuế, quy định khác của pháp luật có liên quan.$md$,$md$Luật quản lý thuế 2025_Điều13$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K3$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 3$md$,$md$Hộ kinh doanh, cá nhân kinh doanh thực hiện khai thuế, tính thuế đối với
từng loại thuế theo kỳ tính thuế. Cơ quan thuế căn cứ vào cơ sở dữ liệu quản lý
thuế cung cấp thông tin để hỗ trợ hộ kinh doanh, cá nhân kinh doanh trong việc
khai thuế và tính thuế.$md$,$md$Luật quản lý thuế 2025_Điều13$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K4$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 4$md$,$md$Đối với hộ kinh doanh, cá nhân kinh doanh có hoạt động kinh doanh trên
nền tảng thương mại điện tử, nền tảng số khác:
nền tảng số khác có chức năng đặt hàng trực tuyến và chức năng thanh toán, chủ
quản nền tảng thương mại điện tử, nền tảng số khác (trong nước hoặc nước ngoài)
<!-- Page Break -->
## Page 13
13
có trách nhiệm khấu trừ, khai thay và nộp thay số thuế đã khấu trừ của hộ kinh
doanh, cá nhân kinh doanh;
nền tảng số khác không có chức năng đặt hàng trực tuyến và chức năng thanh
toán, hộ kinh doanh, cá nhân kinh doanh trực tiếp khai thuế, tính thuế và nộp thuế
theo quy định.$md$,$md$Luật quản lý thuế 2025_Điều13$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K4_Da$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm a$md$,$md$Trường hợp có hoạt động kinh doanh trên nền tảng thương mại điện tử,$md$,$md$Luật quản lý thuế 2025_Điều13_K4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K4_Db$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm b$md$,$md$Trường hợp có hoạt động kinh doanh trên nền tảng thương mại điện tử,$md$,$md$Luật quản lý thuế 2025_Điều13_K4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K5$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 5$md$,$md$Chính phủ quy định chỉ tiết Điều này và các nội dung sau: việc quyết
toán thuế và xử lý tiền thuế, khoản thu khác nộp thừa; phạm vi trách nhiệm, cách
thức các chủ quản nền tảng thương mại điện tử, nền tảng số khác thực hiện khấu
trừ, khai thay và nộp thay số thuế đã khấu trừ của hộ kinh doanh, cá nhân kinh
doanh; trách nhiệm khai thay, nộp thuế thay của tổ chức trong trường hợp hợp tác
kinh doanh với hộ kinh doanh, cá nhân kinh doanh, ký hợp đồng với hộ kinh
doanh, cá nhân kinh doanh làm đại lý bán đúng giá đối với xổ số, bảo hiểm, bán
hàng đa cấp.$md$,$md$Luật quản lý thuế 2025_Điều13$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều13_K6$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 6$md$,$md$Bộ trưởng Bộ Tài chính quy định hồ sơ, thủ tục kê khai doanh thu, kê
khai thuế, nộp thuế và hoàn thuế, chế độ kế toán áp dụng đối với hộ kinh doanh,
cá nhân kinh doanh.
Mục 3
NỌP THUÉ, KHOẢN THU KHÁC, TIỀN CHẬM NỘP, TIỀN PHẠT;
