phạt được cấp chứng từ nộp tiền. Trường hợp số tiền thuế, khoản thu khác, tiền
chậm nộp, tiền phạt phải nộp đã được cơ quan quản lý thuế cung cấp mã định
danh khoản phải nộp thì người nộp thuế nộp theo mã định danh khoản phải nộp.
Cơ quan, tổ chức thu tiền thuế, khoản thu khác, tiền chậm nộp, tiền phạt
quy định tại khoản 2 Điều này khi cấp chứng từ nộp tiền cho người nộp thuế
