insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều15_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Người nộp thuế có số tiền thuế, khoản thu khác, tiền chậm nộp, tiền phạt
nộp thừa được bù trừ số tiền thuế, khoản thu khác, tiền chậm nộp, tiền phạt nộp
thừa với số tiền thuế, khoản thu khác, tiền chậm nộp, tiền phạt phải nộp hoặc được
hoàn trả số tiền thuế, khoản thu khác, tiền chậm nộp, tiền phạt nộp thừa khi người
nộp thuế không còn tiền thuế nợ. Việc bù trừ trong cùng hoặc giữa các loại thuế,
khoản thu khác, tiền chậm nộp, tiền phạt đo Hệ thống thông tin quản lý thuế thực
hiện tự động hoặc theo đề nghị của người nộp thuế theo hướng dẫn của Bộ trưởng
Bộ Tài chính.
Trường hợp người nộp thuế có số tiền thuế giá trị gia tăng nộp thừa khi
nhập khẩu hàng hóa và đã thực hiện kê khai khấu trừ số tiền thuế nộp thừa với cơ
quan thuế thì việc xử lý số tiền thuế đã khấu trừ, nộp thừa thực hiện theo quy định
của Bộ trưởng Bộ Tài chính.$md$,$md$Luật quản lý thuế 2025_Điều15$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
