insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều16_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Các trường hợp phải nộp tiền chậm nộp bao gồm:
thời hạn gia hạn nộp quy định tại Điều 14 của Luật này;
số tiền thuế, khoản thu khác phải nộp hoặc giảm số tiền thuế, khoản thu khác đã
được miễn, giảm, hoàn, không thu;
tra phát hiện người nộp thuế khai thiếu số tiền thuế, khoản thu khác phải nộp hoặc
phát hiện số tiền thuế, khoản thu khác đã hoàn, đã miễn, đã giảm, đã không thu lớn
hơn số tiền thuế, khoản thu khác được hoàn, được miễn, được giảm, không thu;
Luật này;
quy định tại điểm a khoản 2 Điều 44 đối với hành vi quy định tại khoản 2 Điều 45
của Luật này và trường hợp quy định tại điểm b khoản 2 Điều 44 của Luật này;
thu khác, cơ quan, tổ chức được giao quản lý các khoản thu thuộc ngân sách nhà
nước chậm nộp vào ngân sách nhà nước đối với số tiền đã thu được thì phải nộp
tiên chậm nộp đối với số tiền nộp chậm theo quy định;
khác thay cho người nộp thuế theo quy định của pháp luật về thuế và quy định
khác của pháp luật có liên quan nộp tiền không đầy đủ, không đúng thời hạn theo
quy định của pháp luật thì có trách nhiệm nộp tiền chậm nộp theo quy định thay
cho người nộp thuế;
tượng chịu thuế được tổ chức tín dụng bảo lãnh số thuế phải nộp thực hiện theo
quy định của pháp luật về thuế xuất khẩu, thuế nhập khâu.$md$,$md$Luật quản lý thuế 2025_Điều16$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
