insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều17_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Hoàn thành nghĩa vụ nộp thuế trong trường hợp giải thể, phá sản, chấm
dứt hoạt động, không hoạt động tại địa chỉ đã đăng ký: ˆ
tác xã, liên hiệp hợp tác xã giải thể được thực hiện theo quy định của pháp luật về
doanh nghiệp, pháp luật về các tổ chức tín dụng, pháp luật về kinh doanh bảo
hiểm, pháp luật về hợp tác xã và quy định khác của pháp luật có liên quan;
tác xã, liên hiệp hợp tác xã phá sản được thực hiện theo quy định của pháp luật về
phục hồi, phá sản;
ty hợp danh chấm dứt hoạt động, không hoạt động tại địa chỉ đã đăng ký chưa
hoàn thành nghĩa vụ nộp thuế thì chủ sở hữu doanh nghiệp tư nhân, chủ sở hữu
công ty trách nhiệm hữu hạn một thành viên, thành viên hợp danh hoàn thành
nghĩa vụ nộp thuế theo quy định của pháp luật về doanh nghiệp; công ty trách
nhiệm hữu hạn hai thành viên trở lên, công ty cổ phần chấm dứt hoạt động, không
hoạt động tại địa chỉ đã đăng ký chưa hoàn thành nghĩa vụ nộp thuế thì cổ đông
<!-- Page Break -->
## Page 19
19
góp vốn, thành viên góp vốn chịu trách nhiệm hoàn thành nghĩa vụ nộp thuế theo
quy định của pháp luật về doanh nghiệp;
động tại địa chỉ đã đăng ký sản xuất, kinh doanh chưa hoàn thành nghĩa vụ nộp
thuế thì phần tiền thuế nợ còn lại do chủ hộ kinh doanh, cá nhân chịu trách nhiệm
hoàn thành nghĩa vụ nộp thuế;
động tại địa chỉ đã đăng ký mà chưa hoàn thành nghĩa vụ nộp thuế thì chịu trách
nhiệm hoàn thành nghĩa vụ nộp thuế của đơn vị phụ thuộc;
hạn một thành viên, thành viên hợp danh, chủ hộ kinh doanh, cá nhân kinh doanh
chịu trách nhiệm hoàn thành nghĩa vụ nộp thuế và các nghĩa vụ có liên quan đến
hồ sơ thuế của doanh nghiệp tư nhân, công ty trách nhiệm hữu hạn một thành viên,
công ty hợp danh, hộ kinh doanh, cá nhân kinh doanh không hoạt động tại địa chỉ
đã đăng ký.$md$,$md$Luật quản lý thuế 2025_Điều17$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
