insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều17_K3$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 3$md$,$md$Hoàn thành nghĩa vụ nộp thuế trong trường hợp người nộp thuế là người
đã chết, người bị Tòa án tuyên bố là đã chết, mắt tích hoặc mất năng lực hành vi
dân sự:
thành nghĩa vụ nộp thuế của người đã chết, người bị Tòa án tuyên bế là đã chết
trong phần di sản của người đã chết, người bị Tòa án tuyên bố là đã chết để lại
hoặc phần tài sản người thừa kế được chia tại thời điểm nhận thừa kế. Trong
trường hợp không có người thừa kế hoặc tất cả những người thừa kế từ chối nhận
di sản thừa kế thì việc hoàn thành nghĩa vụ nộp thuế của người đã chết, người bị
Tòa án tuyên bố là đã chết thực hiện theo quy định của pháp luật về dân sự;
hoàn thành nghĩa vụ nộp thuế của người bị Tòa án tuyên bố mắt năng lực hành vi
dân sự trong phân tài sản của người đó;
là đã chết hoặc mất năng lực hành vi dân sự thì số tiền thuế nợ đã xóa theo quy
định tại Điều 21 của Luật này được phục hồi lại, nhưng không bị tính tiền chậm
nộp cho thời gian bị tuyên bố là đã chết hoặc mắt năng lực hành vi dân sự;
thành nghĩa vụ nộp thuế của người bị Tòa án tuyên bố mất tích bằng tài sản của
người đó theo quyết định của Tòa án.$md$,$md$Luật quản lý thuế 2025_Điều17$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
