insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều17_K6$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 6$md$,$md$Hoàn thành nghĩa vụ nộp thuế trong trường hợp chuyên nhượng dự án
đầu tư, chuyển nhượng vốn:
cư trú tại Việt Nam thực hiện chuyển nhượng dự án đầu tư, chuyển nhượng vốn
có trách nhiệm hoàn thành nghĩa vụ nộp thuế phát sinh từ hoạt động chuyển
nhượng dự án đầu tư, chuyển nhượng vốn theo quy định của pháp luật về thuế;
nước ngoài không cư trú tại Việt Nam chuyền nhượng dự án đầu tư, chuyển
nhượng vốn trực tiếp hoặc gián tiếp cho tổ chức được thành lập theo quy định của
pháp luật Việt Nam, cá nhân cư trú tại Việt Nam thì bên nhận chuyền nhượng có
trách nhiệm xác định, kê khai, khấu trừ và nộp thay số thuế phải nộp của bên
chuyển nhượng. Trường hợp cả bên chuyền nhượng và bên nhận chuyển nhượng
đều là tổ chức được thành lập theo quy định của pháp luật nước ngoài, cá nhân
nước ngoài không cư trú tại Việt Nam thì tổ chức được thành lập theo quy định
của pháp luật Việt Nam nơi bên chuyển nhượng vốn đầu tư trực tiếp hoặc gián
tiếp có trách nhiệm kê khai và nộp thay số thuế phải nộp của bên chuyển nhượng
theo quy định của pháp luật về thuế.$md$,$md$Luật quản lý thuế 2025_Điều17$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
