insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều22_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Kiểm tra thuế tại trụ sở của cơ quan quản lý thuế:
trên cơ sở hồ sơ thuế, cơ sở dữ liệu quản lý thuế có trên Hệ thống thông tin quản
lý thuế; cơ quan hải quan kiểm tra thực tế hàng hóa xuất khẩu, hàng hóa nhập
khẩu trong trường hợp cần thiết và còn đủ điều kiện;
sung thông tin, tài liệu; ban hành quyết định ấn định thuế, xử lý vi phạm hành
chính về quản lý thuế hoặc chuyển sang kiểm tra tại trụ sở người nộp thuế;
luật về hải quan.
