insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều22_K2_Dc$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm c$md$,$md$Trường hợp kiểm tra sau thông quan thực hiện theo quy định của pháp$md$,$md$Luật quản lý thuế 2025_Điều22_K2$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều22_K3$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 3$md$,$md$Kiểm tra thuế tại trụ sở của người nộp thuế:
thuộc diện kiểm tra trước hoàn thuế; trường hợp hồ sơ thuộc diện kiểm tra sau
hoàn thuế đối với hồ sơ thuộc diện hoàn thuế trước theo nguyên tắc quản lý rủi ro
trong quản lý thuế và trong thời hạn 05 năm kể từ ngày ban hành quyết định hoàn
thuế; trường hợp có dấu hiệu vi phạm pháp luật trong lĩnh vực thuế; trường hợp
được lựa chọn theo kế hoạch, chuyên đề; trường hợp theo yêu cầu, đề nghị của cơ
quan, người có thâm quyền; người nộp thuế có rủi ro cao thuộc trường hợp: chia,
tách, sáp nhập, hợp nhất, chuyển đổi loại hình doanh nghiệp, phá sản, giải thể,
chấm dứt hoạt động, cổ phần hóa, chấm dứt hiệu lực mã số thuế, chuyển địa điểm
kinh doanh; trường hợp quy định tại điểm b khoản 2 Điều này; trường hợp kiểm
tra theo yêu cầu của việc giải quyết khiếu nại, tố cáo về thuế; trường hợp hồ sơ
miễn thuế, giảm thuế, không thu thuế của người nộp thuế có rủi ro cao;
hợp quy định tại điểm a khoản này; kiểm tra sau thông quan thực hiện theo quy
định của pháp luật về hải quan; kiểm tra các điều kiện áp dụng chính sách thuế
theo quy định của pháp luật có liên quan.
Trong quá trình kiểm tra, cơ quan hải quan thực hiện kiểm tra thực tế đối
với hàng hóa xuất khẩu, hàng hóa nhập khẩu trong trường hợp cần thiết và còn đủ
điều kiện;
trường hợp chia, tách, sáp nhập, hợp nhất, chuyên đồi loại hình doanh nghiệp, phá
sản, giải thể, chấm dứt hoạt động, cổ phần hóa, chấm dứt hiệu lực mã số thuế,
chuyển địa điểm kinh doanh cơ quan thuế thực hiện kiểm tra tại trụ sở của người
nộp thuế không quá 01 lần trong 01 năm. Quy định này không áp dụng đối với
các trường hợp kiểm tra lại quy định tại điểm a khoản 6 Điều này;
định kiểm tra, trường hợp cần thiết thì có thể gia hạn 01 lần nhưng không quá 20
ngày. Thời hạn kiểm tra thuế đối với doanh nghiệp có giao dịch liên kết không
quá 40 ngày, trường hợp cần thiết thì có thể gia hạn 01 lần nhưng không quá 40
ngày. Trường hợp cần thu thập, trao đổi thông tin với cơ quan thuế nước ngoài thì
thời hạn kiểm tra thuế có thể kéo dài nhưng không quá 02 năm.
Thời hạn kiểm tra quy định tại điểm này không bao gồm thời gian tạm dừng
kiểm tra theo thông báo của cơ quan quản lý thuế.$md$,$md$Luật quản lý thuế 2025_Điều22$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
