insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều22_K4$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 4$md$,$md$Quyền, nghĩa vụ của người nộp thuế trong kiểm tra thuế:
định tại điểm e và điểm r khoản 1 Điều 37 của Luật này và quy định của pháp luật
về kiểm tra chuyên ngành;
<!-- Page Break -->
## Page 28
28
quy định tại điêm p khoản 2 Điều 37 của Luật này và quy định của pháp luật về
kiêm tra chuyên ngành.$md$,$md$Luật quản lý thuế 2025_Điều22$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều22_K4_Da$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm a$md$,$md$Quyền của người nộp thuế trong kiểm tra thuế được thực hiện theo quy$md$,$md$Luật quản lý thuế 2025_Điều22_K4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều22_K4_Db$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm b$md$,$md$Nghĩa vụ của người nộp thuế trong kiểm tra thuế được thực hiện theo$md$,$md$Luật quản lý thuế 2025_Điều22_K4$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều22_K5$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 5$md$,$md$Nhiệm vụ và quyền hạn của cơ quan quản lý thuế trong kiểm tra thuế:
ban hành quyết định kiểm tra; điều chỉnh quyết định kiểm tra; bãi bỏ quyết định
kiểm tra; chỉ đạo đoàn kiểm tra thực hiện đúng nội dung, thời hạn ghi trong quyết
định kiểm tra thuế; áp dụng biện pháp quy định tại Điều 23 của Luật này: tạm
dừng, tạm hoãn, gia hạn thời hạn kiểm tra; quyết định về xử lý vi phạm hành chính
về quản lý thuế theo thẩm quyền hoặc kết luận kiểm tra hoặc thông báo kết quả
kiểm tra hoặc kiến nghị người có thẩm quyền kết luận, ban hành các quyết định
về xử lý vi phạm hành chính về quản lý thuế; chuyển hồ sơ sang cơ quan thanh
tra để tiến hành thanh tra đối với vụ việc phức tạp, phạm vi rộng hoặc chuyển hồ
sơ kiểm tra sang cơ quan điều tra theo quy định của pháp luật đối với trường hợp
qua kiểm tra thuế mà phát hiện hành vi vi phạm trong lĩnh vực thuế có dấu hiệu
trồn thuế, gian lận về thuế đến mức phải truy cứu trách nhiệm hình sự; giải quyết
khiếu nại, tố cáo theo thâm quyển;
thành viên đoàn kiểm tra thực hiện đúng nội dung quyết định kiểm tra; yêu cầu
người nộp thuế cung cấp thông tin, tài liệu, giải trình về vấn đề liên quan đến nội
dung kiểm tra thuế; áp dụng biện pháp quy định tại khoản 2 Điều 23 của Luật này;
quyết định việc niêm phong tài liệu, hàng hóa (nếu có) của đối tượng kiểm tra khi
có căn cứ cho rằng có vi phạm pháp luật trong lĩnh vực thuế; lập biên bản kiểm
tra thuế, biên bản kiểm tra thuế xác định rõ hành vi vi phạm hành chính thì biên
bản kiểm tra thuế của cơ quan thuế được xác định là biên bản vi phạm hành chính;
báo cáo người ra quyết định kiểm tra về kết quả kiểm tra;
hạn sau: thực hiện nhiệm vụ theo sự phân công của trưởng đoàn kiểm tra thuế;
yêu cầu người nộp thuế cung cấp thông tin, tài liệu, giải trình về vấn đề liên quan
đến nội dung kiểm tra thuế được trưởng đoàn phân công thực hiện kiểm tra; báo
cáo kết quả thực hiện nhiệm vụ được giao với trưởng đoàn kiểm tra thuế.$md$,$md$Luật quản lý thuế 2025_Điều22$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
