insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều22_K5_De$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm e$md$,$md$Thành viên đoàn kiểm tra khi thực hiện kiểm tra thuế có nhiệm vụ, quyền$md$,$md$Luật quản lý thuế 2025_Điều22_K5$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều22_K6$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 6$md$,$md$Kiểm tra lại trong hoạt động kiểm tra thuế:
Cơ quan thuế thực hiện kiểm tra lại đối với các vụ việc đã được kết luận,
ban hành quyết định về xử lý vi phạm hành chính về quản lý thuế trong các trường
hợp sau: ban hành quyết định kiểm tra trái thắm quyền; có vi phạm về trình tự,
thủ tục trong quá trình tiến hành kiểm tra dẫn đến sai lệch về nội dung của kết
luận kiểm tra, quyết định về xử lý vi phạm hành chính về quản lý thuế; có sai lầm
<!-- Page Break -->
## Page 29
29
trong việc áp dụng pháp luật khi xử lý vi phạm hành chính về quản lý thuế, kết
luận kiểm tra; nội dung kết luận, xử lý vi phạm hành chính về quản lý thuê không
phù hợp với những chứng cứ thu thập được trong quá trình kiêm tra; người ra
quyết định kiểm tra, trưởng đoàn kiểm tra, thành viên đoàn kiểm tra cố ý làm sai
lệch hồ sơ vụ việc hoặc cô ý kết luận, xử lý vi phạm hành chính về quản lý thuế
trái pháp luật; có dấu hiệu vi phạm pháp luật nghiêm trọng trong lĩnh vực thuế
của người nộp thuế thuộc phạm vi quyết định kiểm tra thuế chưa được phát hiện
đầy đủ qua kiểm tra thuế.
Cơ quan hải quan thực hiện kiểm tra lại đối với các trường hợp có dấu hiệu
vi phạm pháp luật về thuế của người nộp thuế thuộc phạm vi quyết định kiểm tra
thuế nhưng chưa được kiểm tra, phát hiện, chưa được kết luận hoặc đã kết luận
nhưng chưa đầy đủ, chính xác;
tra lại vụ việc của cơ quan quản lý thuế cấp dưới;
định về xử lý vi phạm hành chính về quản lý thuế;
kiểm tra, thành viên đoàn kiểm tra thực hiện nhiệm vụ, quyền hạn theo quy định
tại khoản 5 Điều này.$md$,$md$Luật quản lý thuế 2025_Điều22$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
