insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều23$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 23. Biện pháp áp dụng trong kiểm tra thuế đối với trường hợp có$md$,$md$Biện pháp áp dụng trong kiểm tra thuế đối với trường hợp có
