insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều25_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Các trường hợp ấn định thuế của cơ quan hải quan đối với hàng hóa xuất
khẩu, nhập khẩu:
để khai thuế, tính thuế; không khai thuế hoặc kê khai không chính xác, không đầy
đủ, không trung thực nội dung liên quan đến xác định nghĩa vụ thuế;
pháp luật có liên quan hoặc yêu cầu bằng văn bản của cơ quan hải quan mà người
nộp thuế không cung cấp, từ chối hoặc trì hoãn, kéo dài việc cung cấp hồ sơ, số kế
toán, tài liệu, chứng từ, dữ liệu, số liệu liên quan đến việc xác định chính xác số
tiền thuế phải nộp, miễn, giảm, hoàn, không thu, không chịu thuế theo quy định;
mà không giải trình được các nội dung liên quan đến việc xác định nghĩa vụ thuế
theo quy định của pháp luật;
trung thực, không chính xác số liệu trên số kế toán, hồ sơ, chứng từ, dữ liệu, tài
liệu kế toán để xác định nghĩa vụ thuế;
giá, mã số, xuât xứ hàng hóa không đúng với thực tế, ảnh hưởng đến số thuế phải
nộp, ưu đãi;
thực tế phát sinh, ảnh hưởng đến số tiền thuế phải nộp, miễn, giảm, hoàn, không
thu, không chịu thuế;
