insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều30$md$,$md$Luật quản lý thuế 2025$md$,$md$Điều 30. Nội dung quản lý thuế quốc tế của cơ quan quản lý thuế$md$,$md$Nội dung quản lý thuế quốc tế của cơ quan quản lý thuế$md$,null,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều30_K1$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 1$md$,$md$Đối tượng quản lý thuế quốc tế là các tô chức, cá nhân thuộc phạm vi áp
dụng của các điều ước quốc tế, thỏa thuận quốc tế về thuế mà nước Cộng hòa xã
hội chủ nghĩa Việt Nam là thành viên hoặc là bên ký kết.$md$,$md$Luật quản lý thuế 2025_Điều30$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$Luật quản lý thuế 2025_Điều30_K2$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2$md$,$md$Nhiệm vụ của cơ quan quản lý thuế trong quản lý thuế quốc tế:
quyển ký kết và thực hiện quyền, nghĩa vụ và bảo đảm lợi ích của nước Cộng hòa
xã hội chủ nghĩa Việt Nam theo các điều ước quốc tế;
Hiệp định tránh đánh thuế hai lần, bao gồm: thủ tục thỏa thuận song phương
(MAP), thỏa thuận trước về phương pháp xác định giá tính thuế (APA).
Trong đó, MAP là thỏa thuận bằng văn bản giữa cơ quan thuế Việt Nam và
cơ quan thuế của nước, vùng lãnh thổ đã ký Hiệp định tránh đánh thuế hai lần với
Việt Nam nhằm giải quyết tranh chấp về thuế cho người nộp thuế để tránh bị đánh
thuế hai lần đối với cùng một khoản thu nhập, tài sản hoặc giải quyết việc đánh
thuế của cơ quan thuế một nước không đúng quy định của Hiệp định tránh đánh
thuế hai lần. APA là thỏa thuận bằng văn bản giữa cơ quan thuế với người nộp
thuế (APA đơn phương) hoặc giữa cơ quan thuế Việt Nam với người nộp thuế và
cơ quan thuế của nước, vùng lãnh thổ đã ký Hiệp định tránh đánh thuế hai lần với
Việt Nam (APA song phương, đa phương). Thỏa thuận này nhằm xác định trước
phương pháp xác định giá trong các giao dịch liên kết, phù hợp với nguyên tắc
<!-- Page Break -->
## Page 36
36
giao dịch độc lập để làm căn cứ xác định nghĩa vụ thuế thu nhập doanh nghiệp
của doanh nghiệp có giao dịch liên kết trong một khoảng thời gian cụ thể;
xuất khẩu, nhập khẩu;
thuế hai lần, điều ước quốc tế về thuế khác;
thuế với các cơ quan thuế nước ngoài theo các điều ước quốc tế, thỏa thuận quốc
tế về thuế mà nước Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên hoặc là
bên ký kết và diễn đàn thuế quốc tế phục vụ công tác quản lý thuế;
tổ chức quốc tế phù hợp với quy định của pháp luật Việt Nam và các điều ước
quốc tế, thỏa thuận quốc tế về thuế mà nước Cộng hòa xã hội chủ nghĩa Việt Nam
là thành viên hoặc là bên ký kết;
đối với các doanh nghiệp có giao dịch liên kết và các nghĩa vụ thành viên khác mà
nước Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên hoặc là bên ký kết;
thuế theo tiêu chuẩn trao đổi thông tin của diễn đàn toàn cầu về minh bạch và trao
đổi thông tin phục vụ mục đích thuế.$md$,$md$Luật quản lý thuế 2025_Điều30$md$,null,$md$2026-01-01$md$,null) on conflict(unit_id) do nothing;
